INSERT OR REPLACE INTO cards (id, name, name_cn, name_jp, type, race, attribute, level, atk, def, desc_cn) VALUES
(73359475, 'Noble Knight Peredur', '圣骑士 珀西瓦尔', '聖騎士パーシヴァル', 'Effect Monster', 'Warrior', 'LIGHT', 4, 1900, 300, '①：只要这张卡有「圣剑」装备魔法卡装备，这张卡等级上升1星并变成暗属性。 ②：有「圣剑」装备魔法卡装备的这张卡被送去墓地的场合，以自己墓地1张「圣剑」卡为对象发动。那张卡加入手卡。'),
(34242278, 'Noble Knight''s Shield-Bearer', '圣骑士的持盾者', '聖騎士の盾持ち', 'Effect Monster', 'Warrior', 'LIGHT', 4, 800, 1300, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：这张卡召唤·特殊召唤成功的场合，从自己墓地把1只光属性怪兽除外才能发动。自己从卡组抽1张。 ②：把手卡·场上的这张卡除外才能发动。从卡组把1只6星以下的兽族·风属性怪兽加入手卡。'),
(7721912, 'Noble Knight''s Spearholder', '圣骑士的持枪者', '聖騎士の槍持ち', 'Effect Monster', 'Warrior', 'LIGHT', 2, 800, 400, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合，以自己场上1只8星以下的怪兽为对象才能发动。那只怪兽直到结束阶段卡名当作「鲜花同调士」使用，当作调整使用。 ②：把这张卡解放才能发动。从卡组把1张装备魔法卡加入手卡。'),
(55742055, 'Noble Knights of the Round Table', '圆桌的圣骑士', '円卓の聖騎士', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '①：自己结束阶段，自己的场上·墓地的「圣骑士」卡种类的以下效果各能发动1次。 ●3种类以上：从卡组把1张「圣骑士」卡送去墓地。 ●6种类以上：从手卡把1只「圣骑士」怪兽特殊召唤。那之后，可以从手卡把1张「圣剑」装备魔法卡给那只怪兽装备。 ●9种类以上：以自己墓地1只「圣骑士」怪兽为对象才能发动。那只怪兽加入手卡。 ●12种类：自己从卡组抽1张。'),
(88935103, 'Nobledragon Magician', '贵龙的魔术师', '貴竜の魔術師', 'Pendulum Tuner Effect Monster', 'Spellcaster', 'FIRE', 3, 700, 1400, '把这张卡作为同调素材的场合，不是龙族怪兽的同调召唤不能使用，其他的同调素材有使用除「异色眼」怪兽以外的怪兽的场合，这张卡回到持有者卡组最下面。 ①：这张卡在手卡·墓地存在的场合，以自己场上1只7星以上的「异色眼」怪兽为对象才能发动。那只怪兽的等级下降3星，这张卡特殊召唤。'),
(71044499, 'Nobleman of Crossout', '抹杀之使徒', '抹殺の使徒', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '①：以场上1只里侧表示怪兽为对象才能发动。那只里侧表示怪兽破坏并除外。除外的怪兽是反转怪兽的场合，再让双方把双方卡组确认，从那之中由自己把除外的怪兽的同名怪兽全部除外。'),
(17449108, 'Nobleman of Extermination', '扑灭之使徒', '撲滅の使徒', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '盖放的1张魔法或者陷阱卡破坏并且从游戏中除外。陷阱卡的场合把双方卡组确认，和破坏陷阱卡同名卡全部从游戏除外。'),
(65878864, 'Nobleman-Eater Bug', '食使徒虫', '使徒喰い虫', 'Flip Effect Monster', 'Insect', 'EARTH', 5, 900, 1200, '反转：场上2只怪兽破坏。'),
(81101309, 'Noctilucent Train Bleu Traveler', NULL, NULL, 'Effect Monster', 'Machine', 'EARTH', 10, 2500, 2500, NULL),
(70333910, 'Noctovision Dragon', '夜视龙', 'ノクトビジョン・ドラゴン', 'Effect Monster', 'Dragon', 'DARK', 7, NULL, 2800, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有龙族·暗属性怪兽特殊召唤的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡作为连接素材送去墓地的场合才能发动。自己抽1张。 ③：自己场上的里侧表示卡为对象的魔法·陷阱·怪兽的效果由对方发动时，把墓地的这张卡除外才能发动。那个效果无效。这个回合，对方不能把那些里侧表示卡作为效果的对象。'),
(72238166, 'Node Ryzeal', '节极・雷热涡炉', 'ノード・ライゼオル', 'Effect Monster', 'Thunder', 'FIRE', 4, 1400, 1600, '这个卡名的①的方法的特殊召唤1回合只能有1次，②的效果1回合只能使用1次。 ①：自己的场上或墓地有超量怪兽存在的场合，这张卡可以从手卡特殊召唤。这个方法特殊召唤过的回合，自己不是4阶超量怪兽不能从额外卡组特殊召唤。 ②：从自己的手卡·场上把1张卡送去墓地，以「节式阳极雷火沸动机」以外的自己墓地1只「雷火沸动」怪兽为对象才能发动。那只怪兽效果无效守备表示特殊召唤。'),
(6609736, 'Noh-P.U.N.K. Deer Note', '能－朋.克.鹿角音符', 'No－P.U.N.K.ディア・ノート', 'Effect Monster', 'Warrior', 'EARTH', 5, 2100, 1800, '这个卡名的①②的效果1回合各能使用1次。 ①：把手卡1只其他的「朋克」怪兽给对方观看才能发动。手卡的这张卡和给人观看的怪兽之内1只特殊召唤，另1只送去墓地。 ②：这张卡从场上送去墓地的场合，以5星怪兽以外的自己墓地1只「朋克」怪兽为对象才能发动。那只怪兽特殊召唤。这个回合，自己不能把「能朋克 鹿角仙符」特殊召唤。'),
(55920742, 'Noh-P.U.N.K. Foxy Tune', '能－朋.克.狐调', 'No－P.U.N.K.フォクシー・チューン', 'Effect Monster', 'Beast', 'LIGHT', 8, 2300, 2600, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只「朋克」怪兽解放才能发动。这张卡从手卡特殊召唤。 ②：把手卡·场上的这张卡送去墓地才能发动。选自己1张手卡送去墓地，从卡组把1只8星以外的「朋克」怪兽特殊召唤。 ③：1回合1次，这张卡战斗破坏对方怪兽时才能发动。自己基本分回复那只怪兽的原本攻击力的数值。'),
(81914447, 'Noh-P.U.N.K. Ogre Dance', '能－朋.克.鬼曲', 'No－P.U.N.K.オーガ・ナンバー', 'Effect Monster', 'Fiend', 'DARK', 8, 2500, 2000, '这个卡名的①②的效果1回合各能使用1次。 ①：把自己场上1只「朋克」怪兽解放才能发动。这张卡从手卡特殊召唤。 ②：把手卡·场上的这张卡送去墓地才能发动。从卡组把1只8星以外的「朋克」怪兽加入手卡。 ③：1回合1次，对方把怪兽的效果发动时才能发动。这张卡的攻击力直到回合结束时上升那只对方怪兽的原本攻击力数值。'),
(75046994, 'Noh-P.U.N.K. Rising Scale', '能－朋.克.跃鳞', 'No－P.U.N.K.ライジング・スケール', 'Effect Monster', 'Sea Serpent', 'WATER', 8, 2400, 2400, '这个卡名的①②③的效果1回合各能使用1次。 ①：从自己的手卡·墓地把这张卡以外的1张「朋克」卡除外才能发动。这张卡从手卡特殊召唤。 ②：这张卡特殊召唤的场合，支付600基本分才能发动。从自己的卡组·墓地选8星怪兽以外的1只「朋克」怪兽加入手卡或特殊召唤。 ③：对方场上的攻击力2500以上的怪兽把效果发动时才能发动。那只怪兽变成里侧守备表示。'),
(19535693, 'Noh-P.U.N.K. Ze Amin', '能－朋.克.世阿泯', 'No－P.U.N.K.セアミン', 'Tuner Monster', 'Psychic', 'EARTH', 3, 600, 600, '这个卡名的①②的效果1回合各能使用1次。 ①：支付600基本分才能发动。从卡组把「能朋克 世阿弥」以外的1只「朋克」怪兽加入手卡。 ②：这张卡被送去墓地的场合，以自己场上1只「朋克」怪兽为对象才能发动。那只怪兽的攻击力上升600。'),
(45620686, 'Noisy Gnat', '骚骚虫', '騒々虫', 'Effect Monster', 'Insect', 'EARTH', 2, 700, 300, '把这张卡从手卡送去墓地发动。场上存在的1只怪兽的等级直到结束阶段时上升1星。'),
(92887027, 'Nomadic Force', '流浪佣兵部队', 'ながれ者傭兵部隊', 'Effect Monster', 'Warrior', 'WIND', 4, 1700, 1000, '这张卡战斗破坏对方怪兽送去墓地时，把这张卡解放才能发动。选择对方场上里侧守备表示存在的1只怪兽破坏。'),
(76848240, 'Non Aggression Area', '绝对不可侵领域', '絶対不可侵領域', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '在自己的准备阶段才能发动。丢弃1张手卡。在下一个对方的回合中，对方不能进行通常召唤和特殊召唤。'),
(27581098, 'Non-Fusion Area', '融合禁止地区', '融合禁止エリア', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '双方玩家不能进行融合召唤。'),
(20065549, 'Non-Spellcasting Area', '绝对魔法禁止区域', '絶対魔法禁止区域', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '场上所有表侧表示的效果怪兽以外的怪兽不受魔法效果的影响。'),
(32623004, 'Nopenguin', '否定企鹅', '否定ペンギン', 'Effect Monster', 'Aqua', 'WATER', 3, 1600, 100, '这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，「企鹅」卡的效果从场上回到手卡的卡不回到手卡而除外。 ②：这张卡在墓地存在，「企鹅」怪兽的效果发动时发动。这张卡特殊召唤。'),
(65626958, 'Nordic Beast Gullinbursti', '极星兽 古林布尔斯提', '極星獣グリンブルスティ', 'Tuner Monster', 'Beast', 'LIGHT', 3, 300, 100, '这张卡可以作为「极星」调整的代替而成为同调素材。这个卡名的①②的效果1回合各能使用1次。 ①：这张卡召唤·特殊召唤成功的场合才能发动。从手卡把1只「极星」怪兽特殊召唤。 ②：以「极星兽 古林布尔斯提」以外的自己墓地1只「极星」怪兽为对象才能发动。那只怪兽加入手卡。'),
(15394084, 'Nordic Beast Token', '极星兽 坦格里斯尼尔', '極星獣タングリスニ', 'Token', 'Beast', NULL, NULL, NULL, NULL, NULL),
(42793609, 'Nordic Relic Brisingamen', '极星宝 布里希嘉·曼', '極星宝ブリージンガ・メン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己以及对方场上表侧表示存在的怪兽各1只发动。选择的自己怪兽的攻击力直到结束阶段时变成和选择的对方怪兽的原本攻击力相同攻击力。'),
(55154048, 'Nordic Relic Draupnir', '极星宝 德罗普尼尔', '極星宝ドラウプニル', 'Spell Card', 'Equip', NULL, NULL, NULL, NULL, '名字带有「极神」或者「极星」的怪兽才能装备。装备怪兽的攻击力上升800。场上表侧表示存在的这张卡被卡的效果破坏的场合，可以从自己卡组把1张名字带有「极星宝」的卡加入手卡。'),
(15286412, 'Nordic Relic Gungnir', '极星宝 冈格尼尔', '極星宝グングニル', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '把自己场上表侧表示存在的1只名字带有「极神」或者「极星」的怪兽从游戏中除外，选择场上存在的1张卡发动。选择的卡破坏。发动后第2次的自己的结束阶段时，为这个效果发动而从游戏中除外的怪兽表侧攻击表示回到场上。'),
(7320132, 'Nordic Relic Hlidskjalf', '极星宝 希利德斯凯拉夫', '極星宝フリドスキャルヴ', 'Spell Card', 'Normal', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：从卡组把1只「极星」怪兽特殊召唤。只要这个效果特殊召唤的怪兽表侧表示存在，自己不是「极神」怪兽不能从额外卡组特殊召唤。 ②：把墓地的这张卡除外才能发动。从卡组把1只「极星」怪兽加入手卡。那之后，选1张手卡回到卡组。'),
(89792713, 'Nordic Relic Laevateinn', '极星宝 雷瓦汀', '極星宝レーヴァテイン', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择这个回合战斗破坏怪兽的场上表侧表示存在的1只怪兽才能发动。选择的怪兽破坏。不能对应这张卡的发动把魔法·陷阱·效果怪兽的效果发动。'),
(86827882, 'Nordic Relic Megingjord', '极星宝 梅金吉奥德', '極星宝メギンギョルズ', 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, '选择自己场上表侧表示存在的1只名字带有「极神」或「极星」的怪兽发动。直到结束阶段时为止，那只怪兽的攻击力·守备力变成原本攻击力·守备力的两倍。这个回合被选择的怪兽不能直接攻击对方玩家。'),
(64797746, 'Nordic Relic Svalinn', '极星宝 斯瓦林', '極星宝スヴァリン', 'Trap Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的①②的效果1回合只能有1次使用其中任意1个。 ①：自己场上有「极神」怪兽存在的场合才能发动。对方场上的全部表侧表示的卡的效果直到回合结束时无效化。 ②：把自己场上1只「极星」怪兽解放，以自己墓地1只「极神」怪兽为对象才能发动。那只怪兽特殊召唤。'),
(91011603, 'Nordic Smith Ivaldi', '极星工 伊瓦尔迪', '極星工イーヴァルディ', 'Effect Monster', 'Warrior', 'EARTH', 4, 1500, 700, '这个卡名的①②的效果1回合各能使用1次。 ①：自己场上有「极神」怪兽或者「极星」怪兽存在的场合才能发动。这张卡从手卡特殊召唤。 ②：这张卡召唤·特殊召唤成功的场合才能发动。从卡组把1张「极星宝」卡加入手卡。'),
(14152862, 'Norito the Moral Leader', '风纪宫司 祝词', '風紀宮司ノリト', 'XYZ Monster', 'Spellcaster', 'LIGHT', 6, 2700, 2000, '魔法师族6星怪兽×2 1回合1次，对方把魔法·陷阱卡发动时把这张卡1个超量素材取除才能发动。那个发动无效并破坏。'),
(662854, 'Noritoshi in Darkest Rainment', NULL, NULL, 'Link Monster', 'Spellcaster', 'DARK', NULL, 2500, NULL, NULL),
(79936051, 'Northern Cross Fire', NULL, NULL, 'Trap Card', 'Normal', NULL, NULL, NULL, NULL, NULL),
(61944066, 'Nouvelles Recipe Book "Recettes de Nouvellez"', 'Recettes de Nouvellez～饿魔新飨的食谱～', 'Recettes de Nouvellez～ヌーベルズのレシピ帳～', 'Spell Card', 'Continuous', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：只要自己场上有「新式魔厨」怪兽卡存在，对方场上的表侧表示怪兽变成攻击表示。 ②：每次仪式怪兽的效果让怪兽被解放，对方支付850基本分。 ③：1回合1次，自己把仪式怪兽特殊召唤的场合，以那之内的1只为对象才能发动。除永续魔法卡外的1张「新式魔厨」卡或「食谱」卡从卡组加入手卡，作为对象的怪兽的等级上升1星。'),
(15388353, 'Nouvelles Restaurant "At Table"', '饿魔新飨餐厅『À Table』', 'Nouvellez Auberge 『À Table』', 'Spell Card', 'Field', NULL, NULL, NULL, NULL, '这个卡名的卡在1回合只能发动1张。 ①：作为这张卡的发动时的效果处理，可以从自己的卡组·墓地选1张「食谱」卡加入手卡。 ②：1回合1次，从手卡让1只仪式怪兽回到卡组最下面才能发动。自己从卡组抽1张。 ③：自己结束阶段，以包含「食谱」卡的自己墓地2张卡为对象才能发动。那些卡用喜欢的顺序回到卡组下面。那之后，自己从卡组抽1张。'),
(48783998, 'Nova Summoner', '神召新星', 'コーリング・ノヴァ', 'Effect Monster', 'Fairy', 'LIGHT', 4, 1400, 800, '①：这张卡被战斗破坏送去墓地时才能发动。从卡组把1只攻击力1500以下的天使族·光属性怪兽特殊召唤。场上有「天空的圣域」存在的场合，可以作为代替把1只「天空骑士 珀耳修斯」特殊召唤。'),
(43694075, 'Novox''s Prayer', '律之祈祷', 'ローの祈り', 'Spell Card', 'Ritual', NULL, NULL, NULL, NULL, '「法理守护者」的降临必要。必须从场上或者手札，牺牲奉献等级合计为7个以上的卡。'),
(25607552, 'Nowru Aries the Vernal Dragon', '华信龙－诺鲁孜・艾蕊丝', '華信龍－ノウルーズ・エリーズ', 'Effect Monster', 'Dragon', 'WIND', 7, 2000, 2500, '这个卡名的①②的效果1回合各能使用1次。 ①：这张卡在墓地存在的场合，从手卡把1只5星以上的怪兽送去墓地才能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。 ②：这张卡被战斗或者对方的效果破坏的场合，以对方场上1张卡为对象才能发动。那张卡除外。'),
(45488703, 'NT8000 - SIRIUS', 'NT8000－天狼星', 'NT８０００－SIRIUS', 'Effect Monster', 'Machine', 'DARK', 8, 2300, 2500, '这个卡名的②③的效果1回合各能使用1次。 ①：连接状态的这张卡不会被战斗破坏。 ②：连接怪兽的效果发动的自己·对方回合，以自己以及对方场上的表侧表示卡各1张为对象才能发动。那2张卡破坏。 ③：这张卡从场上以外送去墓地的场合，若自己场上有暗属性连接怪兽存在则能发动。这张卡特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(51616747, 'Nubian Guard', '努比亚的守卫', 'ヌビアガード', 'Effect Monster', 'Warrior', 'FIRE', 2, 500, 500, '这张卡对对方造成战斗伤害时，可以将自己墓地里的1张永续魔法卡弹回卡组最上面。'),
(51669847, 'Null Power Patron Realm - Vidria', NULL, NULL, 'Spell Card', 'Field', NULL, NULL, NULL, NULL, NULL),
(10666000, 'Number 1: Infection Buzzking', 'No.1 感染蝇王 巴力·西卜', 'No.1 インフェクション・バアル・ゼブル', 'XYZ Monster', 'Fiend', 'DARK', 8, 3000, 2500, '8星怪兽×2只以上 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡超量召唤的场合才能发动。把对方的额外卡组确认，那之内的1张送去墓地。 ②：把这张卡1个超量素材取除，以对方场上1张卡为对象才能发动。那张卡破坏。这个效果把表侧表示怪兽破坏的场合，再给与对方那个攻击力一半数值的伤害。 ③：自己准备阶段才能发动。把对方墓地1张卡作为这张卡的超量素材。'),
(15232745, 'Number 1: Numeron Gate Ekam', 'No.1 源数之门-壹', 'No.1 ゲート・オブ・ヌメロン－エーカム', 'XYZ Monster', 'Machine', 'LIGHT', 1, 1000, 100, '1星怪兽×3 ①：这张卡不会被战斗破坏。 ②：这张卡和对方怪兽进行战斗的伤害步骤结束时，把这张卡1个超量素材取除才能发动。自己场上的全部「源数」怪兽的攻击力直到回合结束时变成2倍。'),
(11411223, 'Number 10: Illumiknight', 'No.10 白辉士 启明者', 'No.10 白輝士イルミネーター', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2400, 2400, '4星怪兽×3 ①：1回合1次，把这张卡1个超量素材取除才能发动。选1张手卡送去墓地，自己从卡组抽1张。'),
(57314798, 'Number 100: Numeron Dragon', '编号100 源数龙', 'No.100 ヌメロン・ドラゴン', 'XYZ Monster', 'Dragon', 'LIGHT', 1, NULL, NULL, '相同阶级的同名「No.」超量怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。这张卡的攻击力直到对方回合结束时上升场上的超量怪兽的阶级合计×1000。 ②：这张卡被效果破坏时才能发动。场上的怪兽全部破坏。那之后，双方选自身墓地1张魔法·陷阱卡在场上盖放。 ③：自己的手卡·场上没有卡的场合，对方怪兽的直接攻击宣言时才能发动。这张卡从墓地特殊召唤。'),
(48739166, 'Number 101: Silent Honor ARK', '编号101 寂静荣耀方舟骑士', 'No.101 S・H・Ark Knight', 'XYZ Monster', 'Aqua', 'WATER', 4, 2100, 1000, '4星怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：把这张卡2个超量素材取除，以对方场上1只特殊召唤的表侧攻击表示怪兽为对象才能发动。那只怪兽在这张卡下面重叠作为超量素材。 ②：场上的这张卡被战斗·效果破坏的场合，可以作为代替把这张卡1个超量素材取除。'),
(49678559, 'Number 102: Star Seraph Sentry', '编号102 辉天使 荣光之环', 'No.102 光天使グローリアス・ヘイロー', 'XYZ Monster', 'Fairy', 'LIGHT', 4, 2500, 2000, '光属性4星怪兽×3 ①：1回合1次，把这张卡1个超量素材取除，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力变成一半，效果无效化。 ②：场上的这张卡被战斗·效果破坏的场合，可以作为代替把这张卡的超量素材全部取除。这个效果适用的回合，自己受到的战斗伤害变成一半。'),
(94380860, 'Number 103: Ragnazero', '编号103 神葬零娘 诸神零', 'No.103 神葬零嬢ラグナ・ゼロ', 'XYZ Monster', 'Fairy', 'WATER', 4, 2400, 1200, '4星怪兽×2 ①：自己·对方回合1次，把这张卡1个超量素材取除，以持有和原本攻击力不同攻击力的对方场上1只攻击表示怪兽为对象才能发动。那只怪兽破坏，自己抽1张。'),
(2061963, 'Number 104: Masquerade', '编号104 假面魔蹈士 闪光', 'No.104 仮面魔踏士シャイニング', 'XYZ Monster', 'Spellcaster', 'LIGHT', 4, 2700, 1200, '4星怪兽×3 ①：1回合1次，自己主要阶段才能发动。对方卡组最上面的卡送去墓地。 ②：自己·对方的战斗阶段对方把怪兽的效果发动时，把这张卡1个超量素材取除才能发动。那个发动无效，给与对方800伤害。'),
(59627393, 'Number 105: Battlin'' Boxer Star Cestus', '编号105 燃烧拳斗士 流星之拳带', 'No.105 BK 流星のセスタス', 'XYZ Monster', 'Warrior', 'FIRE', 4, 2500, 1600, '4星怪兽×3 ①：自己的「燃烧拳击手」怪兽和对方怪兽进行战斗的自己·对方的战斗步骤，把这张卡1个超量素材取除才能发动（同一连锁上最多1次）。直到回合结束时那只对方怪兽的效果只在表侧表示的期间无效化，那只自己怪兽不会被那次战斗破坏，那次战斗发生的对自己的战斗伤害由对方代受。'),
(63746411, 'Number 106: Giant Hand', '编号106 巨岩掌 巨人之手', 'No.106 巨岩掌ジャイアント・ハンド', 'XYZ Monster', 'Rock', 'EARTH', 4, 2000, 2000, '4星怪兽×2 ①：对方场上的怪兽的效果发动时，把这张卡2个超量素材取除，以对方场上1只效果怪兽为对象才能发动。这只怪兽表侧表示存在期间，作为对象的效果怪兽的效果无效化，也不能作表示形式的变更。'),
(88177324, 'Number 107: Galaxy-Eyes Tachyon Dragon', '编号107 银河眼时空龙', 'No.107 銀河眼の時空竜', 'XYZ Monster', 'Dragon', 'LIGHT', 8, 3000, 2500, '8星怪兽×2 ①：自己战斗阶段开始时，把这张卡1个超量素材取除才能发动。这张卡以外的场上的全部表侧表示怪兽的效果无效化，那些攻击力·守备力变成原本数值。这个效果发动过的回合的战斗阶段中每次对方把魔法·陷阱·怪兽的效果发动，这张卡的攻击力直到战斗阶段结束时上升1000，这个回合，这张卡在同1次的战斗阶段中可以作2次攻击。'),
(80117527, 'Number 11: Big Eye', '编号11 大眼', 'No.11 ビッグ・アイ', 'XYZ Monster', 'Spellcaster', 'DARK', 7, 2600, 2000, '7星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以对方场上1只怪兽为对象才能发动（这个效果发动的回合，这张卡不能攻击）。得到那只怪兽的控制权。'),
(19333131, 'Number 12: Crimson Shadow Armor Ninja', 'No.12 机甲忍者 红影', 'No.12 機甲忍者クリムゾン・シャドー', 'XYZ Monster', 'Warrior', 'EARTH', 5, 2400, 1700, '5星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。这个回合，自己场上的「忍者」怪兽不会被战斗·效果破坏。这个效果在对方回合也能发动。'),
(69058960, 'Number 13: Embodiment of Crime', '编号13 该隐魔鬼', 'No.13 ケインズ・デビル', 'XYZ Monster', 'Fiend', 'DARK', 1, 500, 500, '1星怪兽×2 ①：自己·对方回合1次，把这张卡1个超量素材取除才能发动。对方场上的全部怪兽变成表侧攻击表示，并在这个回合可以攻击的场合必须向这张卡作出攻击。 ②：只要自己场上有「No.31 亚伯恶魔」存在，这张卡得到以下效果。 ●持有超量素材的这张卡不会被战斗·效果破坏。 ●向这张卡的攻击发生的对自己的战斗伤害由对方代受。'),
(21313376, 'Number 14: Greedy Sarameya', 'No.14 强欲之死神犬', 'No.14 強欲のサラメーヤ', 'XYZ Monster', 'Beast', 'DARK', 5, 2500, 1500, '5星怪兽×2 ①：只要这张卡在怪兽区域存在，对方的效果发生的对自己的效果伤害由对方代受。 ②：这张卡战斗破坏对方怪兽送去墓地时，把这张卡1个超量素材取除才能发动。持有破坏的那只怪兽的原本攻击力以下的攻击力的场上的怪兽全部破坏。'),
(88120966, 'Number 15: Gimmick Puppet Giant Grinder', '编号15 机关傀偶－巨人杀手', 'No.15 ギミック・パペット－ジャイアントキラー', 'XYZ Monster', 'Machine', 'DARK', 8, 1500, 2500, '8星怪兽×2 ①：1回合最多2次，自己主要阶段1，把这张卡1个超量素材取除，以对方场上1只特殊召唤的怪兽为对象才能发动。那只怪兽破坏。破坏的怪兽是超量怪兽的场合，再给与对方那只怪兽的原本攻击力数值的伤害。'),
(54719828, 'Number 16: Shock Master', 'No.16 色之支配者', 'No.16 色の支配者ショック・ルーラー', 'XYZ Monster', 'Fairy', 'LIGHT', 4, 2300, 1600, '4星怪兽×3 ①：1回合1次，把这张卡1个超量素材取除，宣言卡的种类（怪兽·魔法·陷阱）才能发动。直到对方回合结束时，宣言的种类的卡双方不能发动。'),
(69610924, 'Number 17: Leviathan Dragon', '编号17 海鳄龙', 'No.17 リバイス・ドラゴン', 'XYZ Monster', 'Dragon', 'WATER', 3, 2000, NULL, '3星怪兽×2 ①：没有超量素材的这张卡不能直接攻击。 ②：1回合1次，把这张卡1个超量素材取除才能发动。这张卡的攻击力上升500。'),
(23649496, 'Number 18: Heraldry Patriarch', '编号18 纹章祖 素徽', 'No.18 紋章祖プレイン・コート', 'XYZ Monster', 'Psychic', 'LIGHT', 4, 2200, 2200, '4星怪兽×2 这张卡的①的效果在同一连锁上只能发动1次。 ①：场上有同名怪兽2只以上存在的场合，把这张卡1个超量素材取除才能发动。选那之内的1只，那只怪兽以外的那只怪兽的同名怪兽全部破坏。这个效果在对方回合也能发动。 ②：对方不能把这张卡的效果选的怪兽的同名怪兽召唤·反转召唤·特殊召唤。 ③：这张卡被送去墓地的场合才能发动。从卡组把2只「纹章兽」怪兽送去墓地。'),
(55067058, 'Number 19: Freezadon', '编号19 急冻龙', 'No.19 フリーザードン', 'XYZ Monster', 'Dinosaur', 'WATER', 5, 2000, 2500, '5星怪兽×2 ①：1回合1次，自己的超量怪兽把超量素材取除来让效果发动的场合，取除的1个超量素材可以从这张卡取除。'),
(32453837, 'Number 2: Ninja Shadow Mosquito', '编号2 蚊学忍者 影蚊', 'No.2 蚊学忍者シャドー・モスキート', 'XYZ Monster', 'Insect', 'WIND', 2, NULL, NULL, '2星怪兽×2只以上 ①：这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害变成0。 ②：可以攻击的对方怪兽必须作出攻击。 ③：双方怪兽的攻击宣言时，可以从以下选择1个发动。 ●这张卡1个超量素材取除，给对方场上1只表侧表示怪兽放置1个幻觉指示物。有幻觉指示物放置的怪兽的效果无效化。 ●选有幻觉指示物放置的1只怪兽，给与对方那个攻击力数值的伤害。'),
(42230449, 'Number 2: Numeron Gate Dve', 'No.2 源数之门-贰', 'No.2 ゲート・オブ・ヌメロン－ドゥヴェー', 'XYZ Monster', 'Machine', 'LIGHT', 1, 1000, 100, '1星怪兽×3 ①：这张卡不会被战斗破坏。 ②：这张卡和对方怪兽进行战斗的伤害步骤结束时，把这张卡1个超量素材取除才能发动。自己场上的全部「源数」怪兽的攻击力直到回合结束时变成2倍。'),
(47805931, 'Number 20: Giga-Brilliant', 'No.20 蚁岩土 辉蚁', 'No.20 蟻岩土ブリリアント', 'XYZ Monster', 'Insect', 'LIGHT', 3, 1800, 1800, '3星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。自己场上的全部怪兽的攻击力上升300。'),
(57707471, 'Number 21: Frozen Lady Justice', '编号21 冰结之正义女郎', 'No.21 氷結のレディ・ジャスティス', 'XYZ Monster', 'Aqua', 'WATER', 6, 500, 500, '6星怪兽×2 这张卡也能从自己场上的5阶超量怪兽把1个超量素材取除，在那只超量怪兽上面重叠来超量召唤。 ①：这张卡的攻击力上升这张卡的超量素材数量×1000。 ②：1回合1次，把这张卡1个超量素材取除才能发动。对方场上的守备表示怪兽全部破坏。'),
(73445448, 'Number 22: Zombiestein', '编号22 不乱健', 'No.22 不乱健', 'XYZ Monster', 'Zombie', 'DARK', 8, 4500, 1000, '暗属性8星怪兽×2 这张卡不用超量召唤不能特殊召唤。 ①：1回合1次，这张卡在场上攻击表示存在的场合，把这张卡1个超量素材取除，把1张手卡送去墓地，以对方场上1张表侧表示的卡为对象才能发动。这张卡变成守备表示，作为对象的卡的效果直到回合结束时无效。这个效果在对方回合也能发动。'),
(66547759, 'Number 23: Lancelot, Dark Knight of the Underworld', '编号23 冥界灵骑士 兰斯洛特', 'No.23 冥界の霊騎士ランスロット', 'XYZ Monster', 'Zombie', 'DARK', 8, 2000, 1500, '8星怪兽×2 ①：持有超量素材的这张卡可以直接攻击。 ②：这张卡给与对方战斗伤害时，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽破坏。 ③：1回合1次，这张卡以外的怪兽的效果·魔法·陷阱卡发动时，把这张卡1个超量素材取除发动。那个发动无效。'),
(93713837, 'Number 24: Dragulas the Vampiric Dragon', '编号24 龙血鬼 德古拉斯', 'No.24 竜血鬼ドラギュラス', 'XYZ Monster', 'Wyrm', 'DARK', 6, 2400, 2800, '6星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以从额外卡组特殊召唤的1只表侧表示怪兽为对象才能发动。那只怪兽变成里侧守备表示。这个效果在对方回合也能发动。 ②：表侧表示的这张卡因对方的效果从场上离开，被送去墓地的场合或者被除外的场合才能发动。这张卡里侧守备表示特殊召唤。 ③：这张卡反转的场合发动。选场上1张卡送去墓地。'),
(64554883, 'Number 25: Force Focus', 'No.25 重装光学摄影机 焦点之力', 'No.25 重装光学撮影機フォーカス・フォース', 'XYZ Monster', 'Machine', 'LIGHT', 6, 2800, 2400, '6星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以对方场上1只5星以上的效果怪兽为对象才能发动。那只对方怪兽的效果直到回合结束时无效。这个效果在对方回合也能发动。'),
(39622156, 'Number 26: Spaceway Octobypass', 'No.26 次元孔路 绕道章鱼', 'No.26 次元孔路オクトバイパス', 'XYZ Monster', 'Psychic', 'LIGHT', 3, 800, 2400, '3星怪兽×2 这个卡名的①的效果1回合只能使用1次。 ①：自己·对方的战斗阶段开始时，把这张卡1个超量素材取除才能发动。这次战斗阶段中，只能用1只怪兽攻击，那只怪兽的攻击变成直接攻击。 ②：怪兽直接攻击给与战斗伤害的伤害步骤结束时发动。那只攻击的怪兽的控制权移给从回合玩家来看的对方。'),
(8387138, 'Number 27: Dreadnought Dreadnoid', 'No.27 重型战舰-准无畏舰', 'No.27 弩級戦艦－ドレッドノイド', 'XYZ Monster', 'Machine', 'WATER', 4, 2200, 1000, '4星怪兽×2只以上 这个卡名的①的效果1回合只能使用1次。 ①：这张卡战斗破坏对方怪兽的战斗阶段结束时才能发动。把1只10阶以上的机械族超量怪兽在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤。 ②：场上的这张卡被战斗·效果破坏的场合，可以作为代替把这张卡1个超量素材取除。'),
(53701457, 'Number 28: Titanic Moth', '编号28 泰坦巨蛾', 'No.28 タイタニック・モス', 'XYZ Monster', 'Insect', 'FIRE', 7, 2400, 2200, '7星怪兽×2 ①：自己场上没有其他怪兽存在的场合，这张卡可以直接攻击。那次直接攻击给与对方的战斗伤害变成一半。 ②：这张卡给与对方战斗伤害时，把这张卡1个超量素材取除才能发动。给与对方为对方手卡数量×500伤害。'),
(54191698, 'Number 29: Mannequin Cat', '编号29 招财偶猫', 'No.29 マネキンキャット', 'XYZ Monster', 'Beast', 'LIGHT', 2, 2000, 900, '2星怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，把这张卡1个超量素材取除，以对方墓地1只怪兽为对象才能发动。那只怪兽在对方场上特殊召唤。 ②：这张卡已在怪兽区域存在的状态，对方场上有怪兽特殊召唤的场合，以对方场上1只表侧表示怪兽为对象才能发动。从自己的手卡·卡组·墓地选种族或者属性和那只怪兽相同的1只怪兽特殊召唤。'),
(4997565, 'Number 3: Cicada King', '编号3 地狱蝉王', 'No.3 地獄蝉王ローカスト・キング', 'XYZ Monster', 'Insect', 'WIND', 3, 1200, 2500, '3星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡的表示形式变更的场合才能发动。从自己的手卡·墓地把1只昆虫族怪兽守备表示特殊召唤。 ②：场上的怪兽的效果发动时，把这张卡1个超量素材取除，以那1只怪兽为对象才能发动。那只怪兽的效果无效。那之后，选场上1只昆虫族怪兽，守备力上升500或表示形式变更。'),
(78625448, 'Number 3: Numeron Gate Trini', 'No.3 源数之门-叁', 'No.3 ゲート・オブ・ヌメロン－トゥリーニ', 'XYZ Monster', 'Machine', 'LIGHT', 1, 1000, 100, '1星怪兽×3 ①：这张卡不会被战斗破坏。 ②：这张卡和对方怪兽进行战斗的伤害步骤结束时，把这张卡1个超量素材取除才能发动。自己场上的全部「源数」怪兽的攻击力直到回合结束时变成2倍。'),
(81330115, 'Number 30: Acid Golem of Destruction', '编号30 破灭之酸蚀魔像', 'No.30 破滅のアシッド・ゴーレム', 'XYZ Monster', 'Rock', 'WATER', 3, 3000, 3000, '3星怪兽×2 ①：没有超量素材的这张卡不能攻击。 ②：只要这张卡在怪兽区域存在，自己不能把怪兽特殊召唤。 ③：自己准备阶段发动。这张卡1个超量素材取除或自己受到2000伤害。'),
(95442074, 'Number 31: Embodiment of Punishment', '编号31 亚伯魔鬼', 'No.31 アベルズ・デビル', 'XYZ Monster', 'Fiend', 'DARK', 1, 500, 500, '1星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。对方场上的全部怪兽变成表侧攻击表示，并在这个回合可以攻击的场合必须向这张卡作出攻击。这个效果在对方回合也能发动。 ②：只要自己场上有「No.13 该隐恶魔」存在，这张卡得到以下效果。 ●持有超量素材的这张卡不会被战斗·效果破坏。 ●向这张卡的攻击发生的对自己的战斗伤害由对方代受。'),
(65676461, 'Number 32: Shark Drake', '编号32 海咬龙 鲨龙兽', 'No.32 海咬龍シャーク・ドレイク', 'XYZ Monster', 'Sea Serpent', 'WATER', 4, 2800, 2100, '4星怪兽×3 ①：1回合1次，这张卡的攻击破坏对方怪兽送去墓地时，把这张卡1个超量素材取除才能发动。那只怪兽在对方场上攻击表示特殊召唤。这个效果特殊召唤的怪兽的攻击力下降1000。这个效果特殊召唤的场合，这次战斗阶段中，这张卡只再1次可以攻击。'),
(39139935, 'Number 33: Chronomaly Machu Mech', 'No.33 先史遗产-超兵器 气能', 'No.33 先史遺産－超兵器マシュ＝マック', 'XYZ Monster', 'Machine', 'LIGHT', 5, 2400, 1500, '5星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以持有和原本攻击力不同攻击力的对方场上1只怪兽为对象才能发动。给与对方那只怪兽的攻击力和那个原本攻击力的相差数值的伤害，这张卡的攻击力上升这个效果给与的伤害的数值。'),
(32003338, 'Number 34: Terror-Byte', 'No.34 电算机兽 太字节', 'No.34 電算機獣テラ・バイト', 'XYZ Monster', 'Machine', 'DARK', 3, NULL, 2900, '3星怪兽×3 ①：1回合1次，把这张卡1个超量素材取除，以对方场上1只4星以下的攻击表示怪兽为对象才能发动。那只怪兽的控制权直到结束阶段得到。'),
(90162951, 'Number 35: Ravenous Tarantula', '编号35 贪食捕鸟蛛', 'No.35 ラベノス・タランチュラ', 'XYZ Monster', 'Insect', 'DARK', 10, NULL, NULL, '10星怪兽×2 ①：只要这张卡在怪兽区域存在，自己场上的怪兽的攻击力·守备力上升自己和对方的基本分差的数值。 ②：只要持有超量素材的这张卡在怪兽区域存在，每次对方把怪兽特殊召唤给与对方600伤害。 ③：1回合1次，把这张卡1个超量素材取除才能发动。持有这张卡的攻击力以下的攻击力的对方场上的怪兽全部破坏。'),
(50260683, 'Number 36: Chronomaly Chateau Huyuk', 'No.36 先史遗产-超机关 叉丘', 'No.36 先史遺産－超機関フォーク＝ヒューク', 'XYZ Monster', 'Machine', 'LIGHT', 4, 2000, 2500, '4星「先史遗产」怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到回合结束时变成0。这个效果在对方回合也能发动。 ②：把自己场上1只「先史遗产」怪兽解放，以持有和原本攻击力不同攻击力的对方场上1只怪兽为对象才能发动。那只持有和原本攻击力不同攻击力的对方怪兽破坏。'),
(37279508, 'Number 37: Hope Woven Dragon Spider Shark', '编号37 希望织龙 蜘蛛鲨', 'No.37 希望織竜スパイダー・シャーク', 'XYZ Monster', 'Sea Serpent', 'WATER', 4, 2600, 2100, '水属性4星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：自己或者对方的怪兽的攻击宣言时，把这张卡1个超量素材取除才能发动。对方场上的全部怪兽的攻击力直到回合结束时下降1000。 ②：这张卡被战斗·效果破坏送去墓地时，以这张卡以外的自己墓地1只怪兽为对象才能发动。那只怪兽特殊召唤。'),
(63767246, 'Number 38: Hope Harbinger Dragon Titanic Galaxy', '编号38 希望魁龙 泰坦银河', 'No.38 希望魁竜タイタニック・ギャラクシー', 'XYZ Monster', 'Dragon', 'LIGHT', 8, 3000, 2500, '8星怪兽×2 ①：1回合1次，魔法卡的效果在场上发动时才能发动。那个效果无效，场上的那张卡作为这张卡的超量素材。 ②：对方的攻击宣言时，把这张卡1个超量素材取除才能发动。攻击对象转移为这张卡进行伤害计算。 ③：自己场上的其他的表侧表示的超量怪兽被战斗·效果破坏的场合，以自己场上1只超量怪兽为对象才能发动。那只怪兽的攻击力上升那些破坏的怪兽之内1只的原本攻击力数值。'),
(84013237, 'Number 39: Utopia', '编号39 希望皇霍普', 'No.39 希望皇ホープ', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2500, 2000, '4星怪兽×2 ①：自己或对方的怪兽的攻击宣言时，把这张卡1个超量素材取除才能发动。那次攻击无效。 ②：这张卡没有超量素材的状态被选择作为攻击对象的场合发动。这张卡破坏。'),
(21521304, 'Number 39: Utopia Beyond', '编号39 希望皇极越霍普', 'No.39 希望皇ビヨンド・ザ・ホープ', 'XYZ Monster', 'Warrior', 'LIGHT', 6, 3000, 2500, '6星怪兽×2 这个卡名在规则上也当作「希望皇 霍普」卡使用。 ①：这张卡超量召唤成功的场合发动。对方场上的全部怪兽的攻击力变成0。 ②：1回合1次，把这张卡1个超量素材取除，以自己场上1只超量怪兽和自己墓地1只「希望皇 霍普」怪兽为对象才能发动。那只自己场上的超量怪兽除外，那只墓地的怪兽特殊召唤。那之后，自己回复1250基本分。这个效果在对方回合也能发动。'),
(62517849, 'Number 39: Utopia Double', '编号39 希望皇霍普加倍', 'No.39 希望皇ホープ・ダブル', 'XYZ Monster', 'Warrior', 'LIGHT', 4, NULL, 2500, '4星怪兽×2 这个卡名的效果1回合只能使用1次。 ①：自己·对方回合，把这张卡1个超量素材取除才能发动。从卡组把1张「翻倍机会」加入手卡。那之后，「No.39 希望皇 霍普·翻倍」以外的1只「希望皇 霍普」超量怪兽在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤。这个效果特殊召唤的怪兽的攻击力变成2倍，不能直接攻击。'),
(93777634, 'Number 39: Utopia Rising', '编号39 希望皇霍普升华', 'No.39 希望皇ホープ・ライジング', 'XYZ Monster', 'Warrior', 'LIGHT', 4, NULL, 2000, '4星怪兽×2 这个卡名的①②的效果1回合各能使用1次。 ①：这张卡特殊召唤的场合，以「No.39 希望皇 霍普·升腾」以外的自己墓地1只「No.」超量怪兽为对象才能发动。那只怪兽守备表示特殊召唤。那之后，可以把这张卡的超量素材全部作为那只怪兽的超量素材。 ②：自己把怪兽超量召唤的场合才能发动。这张卡从墓地特殊召唤。这个效果特殊召唤的这张卡从场上离开的场合除外。'),
(84124261, 'Number 39: Utopia Roots', '编号39 希望皇霍普起源', 'No.39 希望皇ホープ・ルーツ', 'XYZ Monster', 'Warrior', 'LIGHT', 1, 500, 100, '1星怪兽×2 ①：自己或者对方怪兽的攻击宣言时，把这张卡1个超量素材取除才能发动。那次攻击无效，那只怪兽是超量怪兽的场合，这张卡的攻击力上升那只怪兽的阶级×500。'),
(4019153, 'Number 4: Numeron Gate Catvari', 'No.4 源数之门-肆', 'No.4 ゲート・オブ・ヌメロン－チャトゥヴァーリ', 'XYZ Monster', 'Machine', 'LIGHT', 1, 1000, 100, '1星怪兽×3 ①：这张卡不会被战斗破坏。 ②：这张卡和对方怪兽进行战斗的伤害步骤结束时，把这张卡1个超量素材取除才能发动。自己场上的全部「源数」怪兽的攻击力直到回合结束时变成2倍。'),
(67557908, 'Number 4: Stealth Kragen', '编号4 剧毒刺胞 隐形蜇拉肯', 'No.4 猛毒刺胞ステルス・クラーゲン', 'XYZ Monster', 'Aqua', 'WATER', 4, 1900, 1500, '水属性4星怪兽×2 ①：场上的表侧表示怪兽变成水属性。 ②：1回合1次，自己·对方的主要阶段才能发动。对方场上1只水属性怪兽破坏，给与对方那个攻击力一半数值的伤害。 ③：超量召唤的这张卡被破坏的场合才能发动。把最多有这张卡持有的超量素材数量的「隐形水母怪碟状幼体」从额外卡组特殊召唤。并且可以再给那些特殊召唤的怪兽各从自己墓地把最多1只水属性怪兽作为那超量素材。'),
(75433814, 'Number 40: Gimmick Puppet of Strings', '编号40 机关傀偶－天堂之弦', 'No.40 ギミック・パペット－ヘブンズ・ストリングス', 'XYZ Monster', 'Machine', 'DARK', 8, 3000, 2000, '8星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。给这张卡以外的场上的表侧表示怪兽全部各放置1个线指示物。 ②：这张卡的①的效果把线指示物放置的场合，下次的对方结束阶段发动。有线指示物放置的怪兽全部破坏，给与对方破坏数量×500伤害。'),
(90590303, 'Number 41: Bagooska the Terribly Tired Tapir', '编号41 泥睡魔兽 貘熟梦', 'No.41 泥睡魔獣バグースカ', 'XYZ Monster', 'Fiend', 'EARTH', 4, 2100, 2000, '4星怪兽×2 这张卡的控制者在每次自己准备阶段把这张卡1个超量素材取除。不能取除的场合，这张卡破坏。 ①：只要这张卡在怪兽区域攻击表示存在，这张卡不会被对方的效果破坏，对方不能把这张卡作为效果的对象。 ②：只要这张卡在怪兽区域守备表示存在，场上的表侧表示怪兽变成守备表示，守备表示怪兽发动的效果无效化。'),
(10389142, 'Number 42: Galaxy Tomahawk', '编号42 星舰・银河战斧', 'No.42 スターシップ・ギャラクシー・トマホーク', 'XYZ Monster', 'Machine', 'WIND', 7, NULL, 3000, '7星怪兽×2 ①：1回合1次，把这张卡2个超量素材取除才能发动。在自己场上把「战鹰衍生物」（机械族·风·6星·攻2000/守0）尽可能特殊召唤。这个效果特殊召唤的衍生物在这个回合的结束阶段破坏。这个效果的发动后，直到回合结束时对方受到的战斗伤害变成0。'),
(56051086, 'Number 43: Manipulator of Souls', 'No.43 魂魄傀儡鬼 灵魂傀儡师', 'No.43 魂魄傀儡鬼ソウル・マリオネッター', 'XYZ Monster', 'Fiend', 'DARK', 2, NULL, NULL, '暗属性2星怪兽×3 ①：1回合1次，把这张卡1个超量素材取除，以自己墓地1只「No.」怪兽为对象才能发动。那只怪兽当作装备卡使用给这张卡装备。 ②：有「No.」卡装备的这张卡不会被战斗·效果破坏。 ③：1回合1次，自己基本分回复时才能发动。这张卡的攻击力上升那个数值，给与对方那个数值的伤害。'),
(80764541, 'Number 44: Sky Pegasus', 'No.44 白天马', 'No.44 白天馬スカイ・ペガサス', 'XYZ Monster', 'Beast', 'LIGHT', 4, 1800, 1600, '4星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以对方场上1只表侧表示怪兽为对象才能发动。对方可以支付1000基本分让这个效果无效。没支付的场合，作为对象的怪兽破坏。'),
(29208536, 'Number 45: Crumble Logos the Prophet of Demolition', 'No.45 灭亡之预言者', 'No.45 滅亡の予言者 クランブル・ロゴス', 'XYZ Monster', 'Zombie', 'EARTH', 2, 2200, NULL, '2星怪兽×2只以上 ①：1回合1次，把这张卡1个超量素材取除，以这张卡以外的场上1张表侧表示的卡为对象才能发动。这只怪兽表侧表示存在期间，作为对象的表侧表示的卡的效果无效化。 ②：只要这张卡的①的效果作为对象的卡在场上表侧表示存在，双方不能把作为对象的卡以及那些同名卡的效果发动。'),
(2978414, 'Number 46: Dragluon', '编号46 神影龙 胶子龙', 'No.46 神影龍ドラッグルーオン', 'XYZ Monster', 'Dragon', 'LIGHT', 8, 3000, 3000, '龙族8星怪兽×2 ①：1回合1次，自己场上没有其他怪兽存在的场合，可以把这张卡1个超量素材取除，从以下效果选择1个发动。 ●从手卡把1只龙族怪兽特殊召唤。 ●以对方场上1只龙族怪兽为对象才能发动。得到那只龙族怪兽的控制权。 ●直到对方回合结束时，对方场上的龙族怪兽不能把效果发动。'),
(31320433, 'Number 47: Nightmare Shark', 'No.47 梦魇鲨', 'No.47 ナイトメア・シャーク', 'XYZ Monster', 'Sea Serpent', 'WATER', 3, 2000, 2000, '3星怪兽×2 ①：这张卡特殊召唤成功时才能发动。从手卡以及自己场上的表侧表示怪兽之中选1只水属性·3星怪兽在这张卡下面重叠作为超量素材。 ②：1回合1次，把这张卡1个超量素材取除，以自己场上1只水属性怪兽为对象才能发动。这个回合，那只怪兽以外的怪兽不能攻击，那只怪兽可以直接攻击。'),
(1426714, 'Number 48: Shadow Lich', '编号48 暗影巫妖', 'No.48 シャドー・リッチ', 'XYZ Monster', 'Zombie', 'DARK', 3, 1800, NULL, '3星怪兽×2 ①：对方回合1次，把这张卡1个超量素材取除才能发动。在自己场上把1只「幻影衍生物」（恶魔族·暗·1星·攻/守500）特殊召唤。 ②：这张卡的攻击力上升自己场上的「幻影衍生物」数量×500。 ③：只要自己场上有「幻影衍生物」存在，对方不能选择这张卡作为攻击对象。'),
(16259549, 'Number 49: Fortune Tune', 'No.49 秘鸟 幸运啾啾鸟', 'No.49 秘鳥フォーチュンチュン', 'XYZ Monster', 'Winged Beast', 'LIGHT', 3, 400, 900, '3星怪兽×2 这个卡名的④的效果1回合只能使用1次。 ①：场上的这张卡不会成为效果的对象。 ②：场上的这张卡被战斗·效果破坏的场合，可以作为代替把这张卡1个超量素材取除。 ③：自己准备阶段发动。自己回复500基本分。 ④：这张卡从场上送去墓地的场合，以自己墓地2只3星怪兽为对象发动。那2只怪兽回到卡组，这张卡回到额外卡组。'),
(90126061, 'Number 5: Doom Chimera Dragon', '编号5 亡胧龙 死亡嵌合龙', 'No.5 亡朧竜 デス・キマイラ・ドラゴン', 'XYZ Monster', 'Dragon', 'DARK', 5, NULL, NULL, '5星怪兽×2只以上 ①：这张卡的攻击力上升这张卡的超量素材数量×1000。 ②：持有超量素材的这张卡可以向对方怪兽全部各作1次攻击。 ③：这张卡进行战斗的战斗阶段结束时，可以从以下效果选择1个发动。 ●以自己墓地1只怪兽为对象才能发动。那只怪兽在这张卡下面重叠作为超量素材。 ●以对方墓地1张卡为对象才能发动。那张卡回到对方卡组最上面。'),
(51735257, 'Number 50: Blackship of Corn', 'No.50 黑玉米号', 'No.50 ブラック・コーン号', 'XYZ Monster', 'Plant', 'DARK', 4, 2100, 1500, '4星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以持有这张卡的攻击力以下的攻击力的对方场上1只怪兽为对象才能发动。那只怪兽送去墓地，给与对方1000伤害。这个效果发动的回合，这张卡不能攻击。'),
(56292140, 'Number 51: Finisher the Strong Arm', 'No.51 怪腕之必杀摔角手', 'No.51 怪腕のフィニッシュ・ホールド', 'XYZ Monster', 'Rock', 'EARTH', 3, 2600, NULL, '3星怪兽×3 ①：这张卡不会被战斗破坏。 ②：这张卡进行战斗的伤害步骤结束时，把这张卡1个超量素材取除才能发动。给这张卡放置1个指示物（最多3个）。 ③：这张卡进行战斗的战斗阶段结束时，这张卡有3个指示物放置的场合才能发动。对方场上的卡全部破坏。'),
(7194917, 'Number 52: Diamond Crab King', 'No.52 钻蟹王', 'No.52 ダイヤモンド・クラブ・キング', 'XYZ Monster', 'Rock', 'EARTH', 4, NULL, 3000, '4星怪兽×2 ①：「No.52 钻蟹王」在自己场上只能有1只表侧表示存在。 ②：1回合1次，把这张卡1个超量素材取除才能发动。直到回合结束时，这张卡的守备力变成0，攻击力变成3000。 ③：这张卡攻击的场合，战斗阶段结束时变成守备表示。 ④：没有超量素材的这张卡被攻击的伤害步骤结束时变成攻击表示。'),
(23998625, 'Number 53: Heart-eartH', '编号53 伪骸神 心地心', 'No.53 偽骸神 Heart－eartH', 'XYZ Monster', 'Fiend', 'DARK', 5, 100, 100, '5星怪兽×3 ①：1回合1次，这张卡被选择作为攻击对象的场合发动。这张卡的攻击力直到回合结束时上升那只攻击怪兽的原本攻击力数值。 ②：场上的这张卡被战斗·效果破坏的场合，可以作为代替把这张卡1个超量素材取除。 ③：没有超量素材的这张卡被效果破坏送去墓地的场合发动。这张卡作为超量素材，从额外卡组把1只「No.92 伪骸神龙 心地心龙」当作超量召唤作特殊召唤。'),
(54366836, 'Number 54: Lion Heart', 'No.54 反骨斗士 狮心', 'No.54 反骨の闘士ライオンハート', 'XYZ Monster', 'Warrior', 'EARTH', 1, 100, 100, '1星怪兽×3 ①：攻击表示的这张卡不会被战斗破坏。 ②：这张卡和对方怪兽进行战斗的伤害计算时1次，把这张卡1个超量素材取除才能发动。那次战斗发生的对自己的战斗伤害由对方代受。 ③：这张卡的战斗让自己受到战斗伤害的场合发动。给与对方为受到的伤害数值的伤害。'),
(46871387, 'Number 55: Gogogo Goliath', '编号55 隆隆隆歌利亚', 'No.55 ゴゴゴゴライアス', 'XYZ Monster', 'Rock', 'EARTH', 4, 2400, 1200, '4星怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：只要这张卡在怪兽区域存在，自己场上的怪兽的守备力上升800。 ②：把这张卡1个超量素材取除，以自己墓地1只岩石族·地属性·4星怪兽为对象才能发动。那只岩石族·地属性怪兽加入手卡。'),
(55935416, 'Number 56: Gold Rat', 'No.56 金鼠', 'No.56 ゴールドラット', 'XYZ Monster', 'Beast', 'LIGHT', 1, 500, 600, '1星怪兽×3 ①：1回合1次，把这张卡1个超量素材取除才能发动。自己从卡组抽1张，那之后选1张手卡回到卡组。'),
(53244294, 'Number 57: Tri-Head Dust Dragon', 'No.57 奋迅龙 三头龙', 'No.57 奮迅竜トレスラグーン', 'XYZ Monster', 'Dragon', 'FIRE', 4, 100, 2600, '4星怪兽×3 ①：这张卡特殊召唤成功时，以对方场上1只表侧表示怪兽为对象才能发动。这张卡的攻击力上升那只怪兽的攻击力数值。 ②：对方场上的卡数量比自己场上的卡多的场合，把这张卡1个超量素材取除，指定没有使用的怪兽区域或者没有使用的魔法与陷阱区域1处才能发动。这张卡得到以下效果。 ●只要这张卡在怪兽区域存在，指定的区域不能使用。'),
(93108839, 'Number 58: Burner Visor', 'No.58 炎压鬼', 'No.58 炎圧鬼バーナー・バイサー', 'XYZ Monster', 'Pyro', 'FIRE', 4, 1000, 1000, '4星怪兽×2 ①：1回合1次，可以从以下效果选择1个发动。 ●以自己场上1只超量怪兽为对象，把这张卡当作装备卡使用给那只怪兽装备。 ●装备的这张卡攻击表示特殊召唤。 ②：装备怪兽可以向对方直接攻击。 ③：装备怪兽给与对方战斗伤害时，丢弃1张手卡才能发动。给与对方500伤害。'),
(82697249, 'Number 59: Crooked Cook', '编号59 背反的料理人', 'No.59 背反の料理人', 'XYZ Monster', 'Warrior', 'FIRE', 4, 2300, 200, '4星怪兽×2 ①：自己场上的卡只有这张卡的场合，这张卡不受其他卡的效果影响。 ②：1回合1次，把这张卡1个超量素材取除才能发动。这张卡以外的自己场上的卡全部破坏。那之后，这张卡的攻击力直到回合结束时上升这个效果破坏送去墓地的怪兽数量×300。这个效果在对方回合也能发动。'),
(9161357, 'Number 6: Chronomaly Atlandis', 'No.6 先史遗产 大西洲巨人', 'No.6 先史遺産アトランタル', 'XYZ Monster', 'Machine', 'LIGHT', 6, 2600, 3000, '6星怪兽×2 ①：这张卡超量召唤成功时，以自己墓地1只「No.」怪兽为对象才能发动。那只怪兽当作装备卡使用给这张卡装备。 ②：这张卡的攻击力上升这张卡的效果装备的怪兽的攻击力一半数值。 ③：1回合1次，把这张卡1个超量素材取除，把这张卡的效果装备的自己的魔法与陷阱区域1张卡送去墓地才能发动。对方基本分变成一半。这个效果发动的回合，自己不能进行战斗阶段。'),
(66011101, 'Number 60: Dugares the Timeless', '编号60 刻不知之杜加雷斯', 'No.60 刻不知のデュガレス', 'XYZ Monster', 'Fiend', 'FIRE', 4, 1200, 1200, '4星怪兽×2 这个卡名的效果1回合只能使用1次。 ①：可以把这张卡2个超量素材取除，从以下效果选择1个发动。 ●自己抽2张。那之后，选自己1张手卡丢弃。下次的自己抽卡阶段跳过。 ●从自己墓地把1只怪兽守备表示特殊召唤。下次的自己主要阶段1跳过。 ●自己场上1只怪兽的攻击力直到回合结束时变成2倍。下次的自己回合的战斗阶段跳过。'),
(29669359, 'Number 61: Volcasaurus', '编号61 火山恐龙', 'No.61 ヴォルカザウルス', 'XYZ Monster', 'Dinosaur', 'FIRE', 5, 2500, 1000, '5星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以对方场上1只表侧表示怪兽为对象才能发动（这个效果发动的回合，这张卡不能直接攻击）。那只对方怪兽破坏，给与对方那个原本攻击力数值的伤害。'),
(31801517, 'Number 62: Galaxy-Eyes Prime Photon Dragon', '编号62 银河眼光子龙皇', 'No.62 銀河眼の光子竜皇', 'XYZ Monster', 'Dragon', 'LIGHT', 8, 4000, 3000, '8星怪兽×2 ①：这张卡进行战斗的伤害计算时1次，把这张卡1个超量素材取除才能发动。这张卡的攻击力只在那次伤害计算时上升场上的超量怪兽的阶级合计×200。 ②：没有「银河眼光子龙」在作为超量素材中的这张卡给与对方的战斗伤害变成一半。 ③：有「银河眼光子龙」在作为超量素材中的这张卡被对方的效果破坏的场合才能发动。发动后第2次的自己准备阶段把这张卡的攻击力变成2倍特殊召唤。'),
(89642993, 'Number 63: Shamoji Soldier', 'No.63 饭勺战士', 'No.63 おしゃもじソルジャー', 'XYZ Monster', 'Fairy', 'LIGHT', 1, NULL, 2000, '1星怪兽×2 这个卡名的效果1回合只能使用1次。 ①：可以把这张卡1个超量素材取除，从以下效果选择1个发动。 ●下次的对方准备阶段开始时，双方玩家从卡组抽1张。 ●双方玩家回复1000基本分。'),
(39972129, 'Number 64: Ronin Raccoon Sandayu', '编号64 古狸三太夫', 'No.64 古狸三太夫', 'XYZ Monster', 'Beast', 'EARTH', 2, 1000, 1000, '兽族2星怪兽×2 ①：只要自己场上有其他的兽族怪兽存在，这张卡不会被战斗·效果破坏。 ②：1回合1次，把这张卡1个超量素材取除才能发动。在自己场上把1只「影武者狸衍生物」（兽族·地·1星·攻?/守0）特殊召唤。这衍生物的攻击力变成和场上的怪兽的最高攻击力相同。'),
(3790062, 'Number 65: Djinn Buster', '编号65 裁断魔人 裁决破坏者', 'No.65 裁断魔人ジャッジ・バスター', 'XYZ Monster', 'Fiend', 'DARK', 2, 1300, NULL, '暗属性2星怪兽×2 ①：对方把怪兽的效果发动时，把这张卡2个超量素材取除才能发动。那个发动无效，给与对方500伤害。'),
(76067258, 'Number 66: Master Key Beetle', 'No.66 霸键甲虫', 'No.66 覇鍵甲虫マスター・キー・ビートル', 'XYZ Monster', 'Insect', 'DARK', 4, 2500, 800, '暗属性4星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以这张卡以外的自己场上1张卡为对象才能发动。这张卡得到以下效果。 ●只要这张卡在怪兽区域存在，作为对象的卡不会被效果破坏。 ●这张卡被战斗·效果破坏的场合，可以作为代替把作为对象的1张自己的卡送去墓地。'),
(35772782, 'Number 67: Pair-a-Dice Smasher', '编号67 天堂骰子锤手', 'No.67 パラダイスマッシャー', 'XYZ Monster', 'Fairy', 'LIGHT', 5, 2100, 2100, '5星怪兽×2只以上 ①：1回合1次，自己主要阶段1把这张卡2个超量素材取除才能发动。双方各掷2次骰子。出现的数目合计大的玩家直到下个回合的结束时不能把怪兽的效果发动，不能攻击宣言。 ②：持有超量素材的这张卡在怪兽区域存在，自己或者对方掷骰子的场合，1回合只有1次可以把那之内1个数目作为7适用。'),
(23085002, 'Number 68: Sanaphond the Sky Prison', '编号68 魔天牢 桑达丰', 'No.68 魔天牢サンダルフォン', 'XYZ Monster', 'Rock', 'DARK', 8, 2100, 2700, '8星怪兽×2 ①：这张卡的攻击力·守备力上升双方墓地的怪兽数量×100。 ②：1回合1次，把这张卡1个超量素材取除才能发动。直到对方回合结束时，这张卡不会被效果破坏，双方不能把墓地的怪兽特殊召唤。'),
(2407234, 'Number 69: Heraldry Crest', '编号69 徽章神 盾徽', 'No.69 紋章神コート・オブ・アームズ', 'XYZ Monster', 'Psychic', 'LIGHT', 4, 2600, 1400, '4星怪兽×3 这个卡名的②的效果1回合只能使用1次。 ①：这张卡特殊召唤的场合发动。这张卡以外的场上的全部超量怪兽的效果无效化。 ②：以场上1只其他的超量怪兽为对象才能发动。这张卡直到结束阶段得到和那只怪兽的原本的卡名·效果相同的卡名·效果。'),
(77571454, 'Number 69: Heraldry Crest - Dark Matter Demolition', '编号69 徽章神 盾徽－神之狂怒', 'No.69 紋章神コート・オブ・アームズ－ゴッド・レイジ', 'XYZ Monster', 'Psychic', 'LIGHT', 4, 3100, 1900, '4星怪兽×5 ①：场上的这张卡不会被战斗·效果破坏。 ②：自己·对方回合1次，把这张卡1个超量素材取除，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的卡名当作「不明」使用。 ③：只要这张卡在怪兽区域存在，对方发动的「不明」的效果无效化。'),
(31086840, 'Number 69: Heraldry Crest - Shatter Stream', '编号69 徽章神 盾徽－神之遮断', 'No.69 紋章神コート・オブ・アームズ－ゴッド・シャーター', 'XYZ Monster', 'Psychic', 'LIGHT', 4, 2800, 1600, '4星怪兽×4 这张卡也能在原本卡名是「No.69 纹章神 盾徽」的自己场上的怪兽上面重叠来超量召唤。这个卡名的效果1回合只能使用1次。 ①：对方场上的怪兽把效果发动时或者对方怪兽的攻击宣言时才能发动。把1只「No.69 纹章神 盾徽-神之愤怒」在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤。那之后，那1只对方怪兽破坏。'),
(82308875, 'Number 7: Lucky Straight', '编号7 幸运条纹', 'No.7 ラッキー・ストライプ', 'XYZ Monster', 'Fairy', 'LIGHT', 7, 700, 700, '7星怪兽×3 ①：把这张卡1个超量素材取除才能发动。掷2次骰子。这张卡的攻击力直到对方回合结束时变成较大方的出现数目×700。出现的数目合计是7的场合，再从以下效果选1个适用。 ●这张卡以外的场上的卡全部送去墓地。 ●从手卡或者自己·对方的墓地选1只怪兽在自己场上特殊召唤。 ●自己从卡组抽3张，那之后选2张手卡丢弃。'),
(80796456, 'Number 70: Malevolent Sin', '编号70 大罪', 'No.70 デッドリー・シン', 'XYZ Monster', 'Insect', 'DARK', 4, 2400, 1200, '4星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除，以对方场上1只怪兽为对象才能发动。那只怪兽直到下次的对方准备阶段除外。 ②：这张卡攻击的伤害步骤结束时才能发动。这张卡的攻击力上升300，阶级上升3阶。'),
(59479050, 'Number 71: Rebarian Shark', '编号71 海鳄巴利安鲨', 'No.71 リバリアン・シャーク', 'XYZ Monster', 'Dragon', 'WATER', 3, NULL, 2000, '3星怪兽×2 ①：1回合1次，以「No.71 海异鲨」以外的自己墓地1只「No.」超量怪兽为对象才能发动。那只怪兽特殊召唤，把这张卡1个超量素材在那只怪兽下面重叠作为超量素材。 ②：这张卡被送去墓地的场合才能发动。从卡组选1张「升阶魔法」魔法卡在卡组最上面放置。'),
(75253697, 'Number 72: Shogi Rook', 'No.72 行列怪兽 战车之飞车', 'No.72 ラインモンスター チャリオッツ・飛車', 'XYZ Monster', 'Beast-Warrior', 'EARTH', 6, 2500, 1200, '6星怪兽×2 ①：1回合1次，把这张卡2个超量素材取除，以对方场上1只表侧表示怪兽和对方场上盖放的1张魔法·陷阱卡为对象才能发动。那些卡破坏。这个效果的发动后，直到回合结束时对方受到的战斗伤害变成一半。'),
(36076683, 'Number 73: Abyss Splash', '编号73 激泷神 邃渊飞溅', 'No.73 激瀧神アビス・スプラッシュ', 'XYZ Monster', 'Warrior', 'WATER', 5, 2400, 1400, '水属性5星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。这张卡的攻击力直到对方回合结束时变成2倍。这个效果的发动后，直到回合结束时这张卡给与对方的战斗伤害变成一半。这个效果在对方回合也能发动。'),
(16037007, 'Number 74: Master of Blades', '编号74 魔力小丑－失落之剑', 'No.74 マジカル・クラウン－ミッシング・ソード', 'XYZ Monster', 'Psychic', 'EARTH', 7, 2700, 2100, '7星怪兽×2 ①：这张卡为对象的魔法·陷阱·怪兽的效果发动时，把这张卡1个超量素材取除才能发动。那个发动无效并破坏。那之后，可以选场上1张卡破坏。'),
(71166481, 'Number 75: Bamboozling Gossip Shadow', '编号75 惑乱之流言暗影', 'No.75 惑乱のゴシップ・シャドー', 'XYZ Monster', 'Spellcaster', 'WIND', 3, 1000, 2600, '3星怪兽×2只以上 这个卡名的②的效果1回合只能使用1次。 ①：1回合1次，对方把怪兽的效果发动时，把这张卡2个超量素材取除才能发动。那个效果变成「双方各自抽1张」。 ②：以自己场上1只其他的「No.」超量怪兽为对象才能发动。把这张卡作为那只怪兽的超量素材（这张卡持有超量素材的场合，那些也全部作为超量素材）。'),
(92015800, 'Number 76: Harmonizer Gradielle', '编号76 谐调光师 格拉递艾儿', 'No.76 諧調光師グラディエール', 'XYZ Monster', 'Fairy', 'LIGHT', 7, 2700, 2100, '7星怪兽×2 这个卡名的③的效果1回合只能使用1次。 ①：这张卡的属性也当作这张卡作为超量素材中的怪兽的各自属性使用。 ②：这张卡不会被和持有和这张卡相同属性的怪兽的战斗破坏，不会被持有和这张卡相同属性的对方怪兽发动的效果破坏。 ③：以对方墓地1只怪兽为对象才能发动。这张卡1个超量素材取除，把作为对象的怪兽在这张卡下面重叠作为超量素材。这个效果在对方回合也能发动。'),
(62541668, 'Number 77: The Seven Sins', '编号77 七宗罪', 'No.77 ザ・セブン・シンズ', 'XYZ Monster', 'Fiend', 'DARK', 12, 4000, 3000, '12星怪兽×2 这张卡也能在自己场上的10·11阶的暗属性超量怪兽上面重叠来超量召唤。这个方法特殊召唤的回合，这张卡的①的效果不能发动。 ①：1回合1次，把这张卡2个超量素材取除才能发动。对方场上的特殊召唤的怪兽全部除外，那之后，从所除外的怪兽之中选1只在这张卡下面重叠作为超量素材。 ②：场上的这张卡被战斗·效果破坏的场合，可以作为代替把这张卡1个超量素材取除。'),
(29085954, 'Number 78: Number Archive', 'No.78 编号系档案馆', 'No.78 ナンバーズ・アーカイブ', 'XYZ Monster', 'Spellcaster', 'LIGHT', 1, NULL, NULL, '1星怪兽×2 ①：1回合1次，把这张卡1个超量素材取除才能发动。自己的额外卡组的卡由对方随机选1张。那是「No.1」～「No.99」其中任意种的「No.」怪兽的场合，那只怪兽在自己场上的这张卡上面重叠当作超量召唤从额外卡组特殊召唤。这个效果特殊召唤的怪兽在结束阶段除外。这个效果的发动后，直到回合结束时自己不能把怪兽特殊召唤。这个效果在对方回合也能发动。'),
(71921856, 'Number 79: Battlin'' Boxer Nova Kaiser', '编号79 燃烧拳斗士 新星之拳环', 'No.79 BK 新星のカイザー', 'XYZ Monster', 'Warrior', 'FIRE', 4, 2300, 1600, '4星怪兽×2 ①：这张卡的攻击力上升这张卡的超量素材数量×100。 ②：1回合1次，自己主要阶段才能发动。把自己的手卡·墓地1只「燃烧拳击手」怪兽作为这张卡的超量素材。 ③：持有超量素材的这张卡被对方破坏送去墓地时，以最多有这张卡持有的超量素材数量的自己墓地的4星以下的「燃烧拳击手」怪兽为对象才能发动。那些怪兽特殊召唤。'),
(47387961, 'Number 8: Heraldic King Genom-Heritage', '编号8 纹章王 基因组继承者', 'No.8 紋章王ゲノム・ヘリター', 'XYZ Monster', 'Psychic', 'LIGHT', 4, 2400, 1800, '4星「纹章兽」怪兽×2 ①：1回合1次，以对方场上1只超量怪兽为对象才能发动。这张卡原本攻击力变成和那只怪兽的攻击力相同，得到和那只怪兽的原本的卡名·效果相同的卡名·效果。那之后，作为对象的怪兽的攻击力变成0，效果无效化。这个效果直到结束阶段适用。'),
(93568288, 'Number 80: Rhapsody in Berserk', '编号80 狂装霸王 狂战狂想曲', 'No.80 狂装覇王ラプソディ・イン・バーサーク', 'XYZ Monster', 'Fiend', 'DARK', 4, NULL, 1200, '4星怪兽×2 这个卡名的①的效果1回合可以使用最多2次。 ①：把这张卡1个超量素材取除，以对方墓地1张卡为对象才能发动。那张卡除外。 ②：以自己场上1只超量怪兽为对象才能发动。自己场上的这张卡当作攻击力上升1200的装备卡使用给那只自己怪兽装备。'),
(49032236, 'Number 81: Superdreadnought Rail Cannon Super Dora', '编号81 超重型炮塔列车 优级多拉炮', 'No.81 超弩級砲塔列車スペリオル・ドーラ', 'XYZ Monster', 'Machine', 'EARTH', 10, 3200, 4000, '10星怪兽×2 ①：自己·对方回合1次，把这张卡1个超量素材取除，以场上1只表侧表示怪兽为对象才能发动。那只表侧表示怪兽直到回合结束时不受自身以外的卡的效果影响。'),
(31437713, 'Number 82: Heartlandraco', '编号82 心园小龙', 'No.82 ハートランドラコ', 'XYZ Monster', 'Dragon', 'EARTH', 4, 2000, 1500, '4星怪兽×2 ①：只要自己场上有魔法卡表侧表示存在，对方不能选择这张卡作为攻击对象。 ②：1回合1次，把这张卡1个超量素材取除才能发动。这个回合，其他的自己怪兽不能攻击，这张卡可以直接攻击。'),
(48928529, 'Number 83: Galaxy Queen', 'No.83 银河女王', 'No.83 ギャラクシー・クィーン', 'XYZ Monster', 'Spellcaster', 'DARK', 1, 500, 500, '1星怪兽×3 ①：1回合1次，把这张卡1个超量素材取除才能发动。自己场上的全部怪兽直到对方回合结束时不会被战斗破坏，向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(26556950, 'Number 84: Pain Gainer', '编号84 获痛者', 'No.84 ペイン・ゲイナー', 'XYZ Monster', 'Insect', 'DARK', 11, NULL, NULL, '11星怪兽×2 这张卡也能在持有超量素材2个以上的自己的8～10阶的暗属性超量怪兽上面重叠来超量召唤。 ①：这张卡的守备力上升自己场上的超量怪兽的阶级合计×200。 ②：只要持有超量素材的这张卡在怪兽区域存在，每次对方把魔法·陷阱卡发动给与对方600伤害。 ③：1回合1次，把这张卡1个超量素材取除才能发动。持有这张卡的守备力以下的守备力的对方场上的怪兽全部破坏。'),
(42421606, 'Number 85: Crazy Box', '编号85 狂箱', 'No.85 クレイジー・ボックス', 'XYZ Monster', 'Fiend', 'DARK', 4, 3000, 300, '4星怪兽×2 ①：这张卡不能攻击。 ②：1回合1次，把这张卡1个超量素材取除才能发动。掷1次骰子，出现的数目的以下效果适用。 ●1：自己基本分变成一半。 ●2：自己从卡组抽1张。 ●3：对方选1张手卡丢弃。 ●4：选场上1张表侧表示的卡，那个效果直到回合结束时无效。 ●5：选场上1张卡破坏。 ●6：这张卡破坏。'),
(63504681, 'Number 86: Heroic Champion - Rhongomyniad', 'No.86 英豪冠军 击灭枪王', 'No.86 H－C ロンゴミアント', 'XYZ Monster', 'Warrior', 'DARK', 4, 1500, 1500, '战士族4星怪兽×2只以上（最多5只） ①：对方结束阶段发动。这张卡1个超量素材取除。 ②：这张卡的超量素材数量让这张卡得到以下效果。 ●1个以上：这张卡不会被战斗破坏。 ●2个以上：这张卡的攻击力·守备力上升1500。 ●3个以上：这张卡不受其他卡的效果影响。 ●4个以上：对方不能把怪兽召唤·特殊召唤。 ●5个以上：1回合1次，可以发动。对方场上的卡全部破坏。'),
(89516305, 'Number 87: Queen of the Night', '编号87 雪月花美神 月下女王', 'No.87 雪月花美神クイーン・オブ・ナイツ', 'XYZ Monster', 'Plant', 'WATER', 8, 3200, 2800, '8星怪兽×3 ①：1回合1次，可以把这张卡1个超量素材取除，从以下效果选择1个发动。这个效果在对方回合也能发动。 ●以对方场上盖放的1张魔法·陷阱卡为对象才能发动。只要这张卡在怪兽区域存在，那张卡不能发动。 ●以场上1只植物族怪兽为对象才能发动。那只植物族怪兽变成里侧守备表示。 ●以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力上升300。'),
(48995978, 'Number 88: Gimmick Puppet of Leo', '编号88 机关傀偶－命运之狮', 'No.88 ギミック・パペット－デステニー・レオ', 'XYZ Monster', 'Machine', 'DARK', 8, 3200, 2300, '8星怪兽×3 这张卡有3个命运指示物被放置时，自己决斗胜利。 ①：1回合1次，自己的魔法与陷阱区域没有卡存在的场合才能发动。这张卡1个超量素材取除，给这张卡放置1个命运指示物。这个效果发动的回合，自己不能进行战斗阶段。'),
(95474755, 'Number 89: Diablosis the Mind Hacker', '编号89 电脑兽 迪亚布罗系司', 'No.89 電脳獣ディアブロシス', 'XYZ Monster', 'Psychic', 'DARK', 7, 2800, 1200, '7星怪兽×2 这个卡名的③的效果1回合只能使用1次。 ①：1回合1次，把这张卡1个超量素材取除才能发动。把对方的额外卡组确认，选那之内的1张里侧表示除外。 ②：这张卡战斗破坏怪兽的战斗阶段结束时，以对方墓地1张卡为对象才能发动。那张卡里侧表示除外。 ③：对方的卡被里侧表示除外的场合才能发动。把里侧表示除外中的对方的卡数量的卡从对方卡组上面里侧表示除外。'),
(1992816, 'Number 9: Dyson Sphere', 'No.9 天盖星 戴森球', 'No.9 天蓋星ダイソン・スフィア', 'XYZ Monster', 'Machine', 'LIGHT', 9, 2800, 3000, '9星怪兽×2 ①：持有比这张卡高的攻击力的怪兽在对方场上存在的场合，自己主要阶段1把这张卡1个超量素材取除才能发动。这个回合，这张卡可以直接攻击。 ②：持有超量素材的这张卡被攻击的战斗步骤才能发动1次。那次攻击无效。 ③：这张卡没有超量素材的状态被选择作为攻击对象时，以自己墓地2只怪兽为对象才能发动。那些怪兽在这张卡下面重叠作为超量素材。'),
(8165596, 'Number 90: Galaxy-Eyes Photon Lord', '编号90 银河眼光子卿', 'No.90 銀河眼の光子卿', 'XYZ Monster', 'Warrior', 'LIGHT', 8, 2500, 3000, '8星怪兽×2 这个卡名的②③的效果1回合各能使用1次。 ①：有「光子」卡在作为超量素材中的这张卡不会被效果破坏。 ②：对方把怪兽的效果发动时，把这张卡1个超量素材取除才能发动。那个效果无效。取除的超量素材是「银河」卡的场合，再把那只怪兽破坏。 ③：对方回合才能发动。从卡组选1张「光子」卡或「银河」卡加入手卡或作为这张卡的超量素材。'),
(84417082, 'Number 91: Thunder Spark Dragon', 'No.91 雷闪龙', 'No.91 サンダー・スパーク・ドラゴン', 'XYZ Monster', 'Dragon', 'LIGHT', 4, 2400, 2000, '4星怪兽×3 ①：1回合1次，可以把这张卡的超量素材的以下数量取除，那个效果发动。 ●3个：这张卡以外的场上的表侧表示怪兽全部破坏。 ●5个：对方场上的卡全部破坏。'),
(97403510, 'Number 92: Heart-eartH Dragon', '编号92 伪骸神龙 心地心龙', 'No.92 偽骸神龍 Heart－eartH Dragon', 'XYZ Monster', 'Dragon', 'DARK', 9, NULL, NULL, '9星怪兽×3 ①：这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害由对方代受。 ②：对方结束阶段把这张卡1个超量素材取除才能发动。把这个回合召唤·特殊召唤·盖放的对方场上的卡全部除外。 ③：持有超量素材的这张卡被破坏送去墓地的场合才能发动。这张卡特殊召唤。 ④：这张卡用自身的效果特殊召唤的场合发动。这张卡的攻击力上升除外中的卡数量×1000。'),
(23187256, 'Number 93: Utopia Kaiser', '编号93 希望皇霍普・凯撒', 'No.93 希望皇ホープ・カイザー', 'XYZ Monster', 'Warrior', 'LIGHT', 12, 2500, 2000, '持有超量素材的相同阶级的「No.」超量怪兽×2只以上 ①：1回合1次，自己主要阶段才能发动。把最多有这张卡的超量素材种类数量的9阶以下而攻击力3000以下的「No.」怪兽从额外卡组效果无效特殊召唤（相同阶级最多1只）。那之后，这张卡1个超量素材取除。这个回合，对方受到的战斗伤害变成一半，自己不能把怪兽特殊召唤。 ②：只要自己场上有其他的「No.」超量怪兽存在，这张卡不会被战斗·效果破坏。'),
(62070231, 'Number 94: Crystalzero', '编号94 极冰姬 水晶零', 'No.94 極氷姫クリスタル・ゼロ', 'XYZ Monster', 'Warrior', 'WATER', 5, 2200, 1600, '水属性5星怪兽×2 ①：把这张卡1个超量素材取除，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力直到自己回合的结束时变成一半。这个效果在对方回合也能发动。'),
(58820923, 'Number 95: Galaxy-Eyes Dark Matter Dragon', 'No.95 银河眼暗物质龙', 'No.95 ギャラクシーアイズ・ダークマター・ドラゴン', 'XYZ Monster', 'Dragon', 'DARK', 9, 4000, NULL, '9星怪兽×3 这张卡也能在自己场上的「银河眼」超量怪兽上面重叠来超量召唤。这张卡不能作为超量召唤的素材。 ①：这张卡超量召唤成功时，从卡组把3只龙族怪兽送去墓地才能发动（同名卡最多1张）。对方从自身卡组把3只怪兽除外。 ②：把这张卡1个超量素材取除才能发动。这个回合，这张卡在同1次的战斗阶段中最多2次可以向怪兽攻击。'),
(55727845, 'Number 96: Dark Mist', 'No.96 黑雾', 'No.96 ブラック・ミスト', 'XYZ Monster', 'Fiend', 'DARK', 2, 100, 1000, '2星怪兽×3 ①：这张卡和对方的表侧表示怪兽进行战斗的攻击宣言时1次，把这张卡1个超量素材取除才能发动。那只对方怪兽的攻击力变成一半，这张卡的攻击力上升那个数值。'),
(28400508, 'Number 97: Draglubion', '编号97 龙影神 引力子龙', 'No.97 龍影神ドラッグラビオン', 'XYZ Monster', 'Dragon', 'DARK', 8, 3000, 3000, '8星怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：对方不能把场上的这张卡作为效果的对象。 ②：把这张卡1个超量素材取除才能发动。从自己的额外卡组·墓地选「No.97 龙影神 引力子龙」以外的龙族「No.」怪兽2种类。那之内的1只特殊召唤，另1只作为那超量素材。这个效果的发动后，直到回合结束时自己不能把怪兽特殊召唤，不用由这个效果特殊召唤的怪兽不能攻击宣言。'),
(55470553, 'Number 98: Antitopian', 'No.98 绝望皇 霍普勒斯', 'No.98 絶望皇ホープレス', 'XYZ Monster', 'Warrior', 'DARK', 4, 2000, 2500, '4星怪兽×2 这个卡名的②的效果1回合只能使用1次。 ①：自己或者对方的怪兽的攻击宣言时，把这张卡1个超量素材取除才能发动。那只怪兽变成守备表示。 ②：这张卡在墓地存在的场合，以场上1只「希望皇 霍普」怪兽为对象才能发动。这张卡守备表示特殊召唤，把作为对象的怪兽在下面重叠作为超量素材。这个效果在对方回合也能发动。'),
(95134948, 'Number 99: Utopia Dragonar', '编号99 希望皇霍普德拉古纳', 'No.99 希望皇ホープドラグナー', 'XYZ Monster', 'Warrior', 'LIGHT', 12, 3000, 3000, '12星怪兽×3只以上 这个卡名的①②的效果1回合各能使用1次。 ①：自己·对方回合，把这张卡2个超量素材取除才能发动（这个效果发动的回合，自己不是超量怪兽不能从额外卡组特殊召唤，其他的自己怪兽不能直接攻击）。把1只「No.1」～「No.100」其中任意种的「No.」怪兽当作超量召唤从额外卡组特殊召唤。 ②：对方怪兽的攻击宣言时才能发动。那只对方怪兽的攻击力变成0。'),
(51543904, 'Number 99: Utopic Dragon', '编号99 希望皇龙霍普德拉古恩', 'No.99 希望皇龍ホープドラグーン', 'XYZ Monster', 'Dragon', 'LIGHT', 10, 4000, 2000, '10星怪兽×3 这张卡也能把手卡1张「升阶魔法」魔法卡丢弃，在自己场上的「希望皇 霍普」怪兽上面重叠来超量召唤。 ①：1回合1次，以自己墓地1只「No.」怪兽为对象才能发动。那只怪兽守备表示特殊召唤。这个效果特殊召唤的怪兽的效果无效化。 ②：这张卡为对象的怪兽的效果发动时，把这张卡1个超量素材取除才能发动。那个发动无效并破坏。'),
(79747096, 'Number C1: Numeron Chaos Gate Sunya', '混沌No.1 混沌源数门-空', 'CNo.1 ゲート・オブ・カオス・ヌメロン－シニューニャ', 'XYZ Monster', 'Machine', 'DARK', 2, 2000, 1000, '2星怪兽×4 这张卡也能在自己场上的「No.1 源数之门-壹」上面重叠来超量召唤。 ①：这张卡超量召唤成功的场合发动。场上的怪兽全部除外。 ②：这张卡被除外的场合，下次的自己准备阶段才能发动。除外的这张卡特殊召唤。自己的场地区域有「源数网络」存在的场合，再给与对方为除外的自己·对方的超量怪兽的攻击力合计数值的伤害。'),
(89477759, 'Number C1000: Numerounius', '混沌No.1000 梦幻虚神 原数天灵', 'CNo.1000 夢幻虚神ヌメロニアス', 'XYZ Monster', 'Fiend', 'LIGHT', 12, -1, -1, '12星怪兽×5 ①：双方回合1次，把这张卡1个超量素材取除才能发动。选场上1只其他怪兽破坏。 ②：战斗阶段结束时发动。场上的其他怪兽全部破坏。那之后，可以从对方墓地选1只怪兽守备表示特殊召唤。 ③：持有超量素材的这张卡被对方的效果破坏送去墓地的场合才能发动。从额外卡组把1只「混沌虚数No.1000 梦幻虚光神 原数天灵·原数天地」特殊召唤，把这张卡作为那超量素材。'),
(12744567, 'Number C101: Silent Honor DARK', '混沌编号101 寂静荣耀黑暗骑士', 'CNo.101 S・H・Dark Knight', 'XYZ Monster', 'Aqua', 'WATER', 5, 2800, 1500, '5星怪兽×3 ①：1回合1次，以对方场上1只特殊召唤的怪兽为对象才能发动。那只怪兽在这张卡下面重叠作为超量素材。 ②：持有超量素材的这张卡被破坏送去墓地时才能发动。这张卡特殊召唤。那之后，自己基本分回复这张卡的原本攻击力的数值。这个效果特殊召唤的这张卡在这个回合不能攻击。这个效果在自己墓地有「No.101 寂静荣誉方舟骑士」存在的场合才能发动和处理。'),
(67173574, 'Number C102: Archfiend Seraph', '混沌编号102 堕光天使 高贵恶魔', 'CNo.102 光堕天使ノーブル・デーモン', 'XYZ Monster', 'Fairy', 'LIGHT', 5, 2900, 2400, '光属性5星怪兽×4 ①：场上的这张卡被战斗·效果破坏的场合，可以作为代替把这张卡2个超量素材取除。 ②：这张卡的超量素材全部被取除的场合发动。给与对方1500伤害。 ③：这张卡有「No.102 光天使 辉环」在作为超量素材的场合，得到以下效果。 ●1回合1次，把这张卡1个超量素材取除，以对方场上1只表侧表示怪兽为对象才能发动。那只对方怪兽的攻击力变成0，效果无效化。'),
(20785975, 'Number C103: Ragnafinity', '混沌编号103 神葬零娘 诸神无限', 'CNo.103 神葬零嬢ラグナ・インフィニティ', 'XYZ Monster', 'Fairy', 'WATER', 5, 2800, 2400, '5星怪兽×3 ①：1回合1次，把这张卡1个超量素材取除，以持有和原本攻击力不同攻击力的对方场上1只怪兽为对象才能发动。给与对方那只怪兽的攻击力和那个原本攻击力的相差数值的伤害，那只怪兽除外。这个效果在对方回合也能发动。 ②：持有超量素材的这张卡被破坏送去墓地时才能发动。这张卡特殊召唤。这个效果在自己墓地有「No.103 神葬零娘 暮零」存在的场合才能发动和处理。'),
(49456901, 'Number C104: Umbral Horror Masquerade', '混沌编号104 假面魔蹈士 黑影', 'CNo.104 仮面魔踏士アンブラル', 'XYZ Monster', 'Spellcaster', 'DARK', 5, 3000, 1500, '5星怪兽×4 ①：这张卡特殊召唤成功时，以场上1张魔法·陷阱卡为对象才能发动。那张卡破坏。 ②：这张卡有「No.104 假面魔蹈士 闪光」在作为超量素材的场合，得到以下效果。 ●1回合1次，对方场上的怪兽的效果发动时，把这张卡1个超量素材取除才能发动。那个发动无效。那之后，可以把对方手卡随机选1张送去墓地，对方基本分变成一半。'),
(85121942, 'Number C105: Battlin'' Boxer Comet Cestus', '混沌编号105 燃烧拳斗士 彗星之拳套', 'CNo.105 BK 彗星のカエストス', 'XYZ Monster', 'Warrior', 'FIRE', 5, 2800, 2000, '5星怪兽×4 ①：这张卡战斗破坏怪兽送去墓地的场合发动。给与对方那只怪兽的原本攻击力一半数值的伤害。 ②：这张卡有「No.105 燃烧拳击手 流星之指套拳士」在作为超量素材的场合，得到以下效果。 ●1回合1次，把这张卡1个超量素材取除，以对方场上1只怪兽为对象才能发动。那只怪兽破坏，把表侧表示怪兽破坏的场合，给与对方那个攻击力数值的伤害。'),
(55888045, 'Number C106: Giant Red Hand', '混沌编号106 溶岩掌 巨人红手', 'CNo.106 溶岩掌ジャイアント・ハンド・レッド', 'XYZ Monster', 'Rock', 'EARTH', 5, 2600, 2000, '5星怪兽×3 ①：这张卡有「No.」怪兽在作为超量素材的场合，得到以下效果。 ●1回合1次，魔法·陷阱·怪兽的效果在场上发动时发动。这张卡1个超量素材取除，这张卡以外的场上的全部表侧表示的卡的效果直到回合结束时无效化。'),
(68396121, 'Number C107: Neo Galaxy-Eyes Tachyon Dragon', '混沌编号107 超银河眼时空龙', 'CNo.107 超銀河眼の時空龍', 'XYZ Monster', 'Dragon', 'LIGHT', 9, 4500, 3000, '9星怪兽×3 ①：1回合1次，把这张卡1个超量素材取除才能发动。这个回合对方不能把场上发动的效果发动，这张卡以外的场上的全部表侧表示卡的效果直到回合结束时无效化。 ②：这张卡有「No.107 银河眼时空龙」在作为超量素材的场合，得到以下效果。 ●把自己场上2只其他怪兽解放才能发动。这个回合，这张卡在同1次的战斗阶段中最多3次可以向怪兽攻击。'),
(33776843, 'Number C15: Gimmick Puppet Giant Hunter', '混沌编号15 机关傀偶－连环杀手', 'CNo.15 ギミック・パペット－シリアルキラー', 'XYZ Monster', 'Machine', 'DARK', 9, 2500, 1500, '9星怪兽×3 ①：1回合1次，把这张卡1个超量素材取除，以对方场上1张卡为对象才能发动。那张卡破坏。这个效果把怪兽破坏的场合，再给与对方那只怪兽的原本攻击力数值的伤害。'),
(7628844, 'Number C32: Shark Drake LeVeiss', '混沌编号32 海咬龙 鲨龙兽・鳄煞', 'CNo.32 海咬龍シャーク・ドレイク・リバイス', 'XYZ Monster', 'Sea Serpent', 'WATER', 5, 3100, 2600, '5星怪兽×4 这张卡也能把手卡1张魔法卡丢弃，在自己场上的4阶「鲨龙兽」超量怪兽上面重叠来超量召唤。 ①：自己·对方回合1次，把这张卡1个超量素材取除，以对方场上1只效果怪兽为对象才能发动。那只怪兽的效果无效，那个攻击力·守备力变成0。 ②：这张卡在同1次的战斗阶段中可以作2次攻击，向守备表示怪兽攻击的场合，给与对方为攻击力超过那个守备力的数值的战斗伤害。'),
(49221191, 'Number C32: Shark Drake Veiss', '混沌编号32 海咬龙 鲨龙兽・白煞', 'CNo.32 海咬龍シャーク・ドレイク・バイス', 'XYZ Monster', 'Sea Serpent', 'WATER', 4, 2800, 2100, '水属性4星怪兽×4 这张卡也能在自己场上的「No.32 海咬龙 鲨龙兽」上面重叠来超量召唤。 ①：自己·对方回合，自己基本分是1000以下的场合，从自己墓地把1只怪兽除外，把这张卡1个超量素材取除，以场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力·守备力直到自己回合的结束时变成0。'),
(56840427, 'Number C39: Utopia Ray', '混沌编号39 希望皇霍普雷', 'CNo.39 希望皇ホープレイ', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2500, 2000, '光属性4星怪兽×3 这张卡也能在自己场上的「No.39 希望皇 霍普」上面重叠来超量召唤。 ①：把这张卡1个超量素材取除才能发动。直到回合结束时这张卡的攻击力上升500，选对方场上1只怪兽那个攻击力直到回合结束时下降1000。这个效果在自己基本分是1000以下的场合才能发动和处理。'),
(66970002, 'Number C39: Utopia Ray V', '混沌编号39 希望皇霍普雷V', 'CNo.39 希望皇ホープレイV', 'XYZ Monster', 'Warrior', 'LIGHT', 5, 2600, 2000, '5星怪兽×3 ①：这张卡被对方破坏时，以自己墓地1只超量怪兽为对象才能发动。那只怪兽回到额外卡组。 ②：这张卡有「希望皇 霍普」怪兽在作为超量素材的场合，得到以下效果。 ●1回合1次，把这张卡1个超量素材取除，以对方场上1只怪兽为对象才能发动。那只怪兽破坏，把表侧表示怪兽破坏的场合，给与对方那个攻击力数值的伤害。'),
(87911394, 'Number C39: Utopia Ray Victory', '混沌编号39 希望皇霍普雷・胜利', 'CNo.39 希望皇ホープレイ・ヴィクトリー', 'XYZ Monster', 'Warrior', 'LIGHT', 5, 2800, 2500, '5星怪兽×3 ①：这张卡攻击的场合，对方直到伤害步骤结束时魔法·陷阱卡不能发动。 ②：这张卡有「希望皇 霍普」怪兽在作为超量素材的场合，得到以下效果。 ●这张卡向对方的表侧表示怪兽攻击宣言时，把这张卡1个超量素材取除才能发动。直到回合结束时，那只对方怪兽的效果无效化，这张卡的攻击力上升那只对方怪兽的攻击力数值。'),
(69170557, 'Number C40: Gimmick Puppet of Dark Strings', '混沌编号40 机关傀偶－魔鬼之弦', 'CNo.40 ギミック・パペット－デビルズ・ストリングス', 'XYZ Monster', 'Machine', 'DARK', 9, 3300, 2000, '9星怪兽×3 ①：这张卡特殊召唤成功的场合发动。有线指示物放置的怪兽全部破坏，自己从卡组抽1张。那之后，给与对方这个效果破坏送去墓地的怪兽之内原本攻击力最高的怪兽的那个数值的伤害。 ②：1回合1次，把这张卡1个超量素材取除才能发动。给对方场上的表侧表示怪兽全部各放置1个线指示物。'),
(32446630, 'Number C43: High Manipulator of Chaos', '混沌No.43 魂魄傀儡鬼神 混沌傀儡师', 'CNo.43 魂魄傀儡鬼神カオス・マリオネッター', 'XYZ Monster', 'Fiend', 'DARK', 3, NULL, NULL, '暗属性3星怪兽×4 ①：自己的衍生物在同1次的战斗阶段中可以作2次攻击。 ②：这张卡有「No.43 魂魄傀儡鬼 灵魂傀儡师」在作为超量素材的场合，得到以下效果。 ●1回合1次，把这张卡1个超量素材取除才能发动。在自己场上把1只「魂魄衍生物」（恶魔族·暗·1星·攻/守?）特殊召唤。这衍生物的攻击力·守备力变成对方基本分一半的数值。'),
(69757518, 'Number C5: Chaos Chimera Dragon', '混沌No.5 亡胧龙 混沌嵌合龙', 'CNo.5 亡朧龍 カオス・キマイラ・ドラゴン', 'XYZ Monster', 'Dragon', 'DARK', 6, NULL, NULL, '6星怪兽×3只以上 ①：这张卡的攻击力上升这张卡的超量素材数量×1000。 ②：这张卡进行攻击的伤害步骤结束时，把这张卡1个超量素材取除才能发动。这张卡向对方怪兽可以继续攻击。 ③：战斗阶段结束时，把基本分支付一半，以自己·对方的墓地的卡合计2张为对象才能发动。那之内的1张在持有者卡组最上面放置，另1张在这张卡下面重叠作为超量素材。'),
(6387204, 'Number C6: Chronomaly Chaos Atlandis', '混沌No.6 先史遗产 混沌大西洲巨人', 'CNo.6 先史遺産カオス・アトランタル', 'XYZ Monster', 'Machine', 'LIGHT', 7, 3300, 3300, '7星怪兽×3 ①：这张卡的效果发动过的回合，对方受到的全部伤害变成0。 ②：1回合1次，以对方场上1只怪兽为对象才能发动。那只对方怪兽当作攻击力上升1000的装备卡使用给这张卡装备。 ③：这张卡有「No.6 先史遗产 大西洲巨人」在作为超量素材的场合，得到以下效果。 ●把这张卡3个超量素材取除，把这张卡的效果装备的「No.」怪兽卡全部送去墓地才能发动。对方基本分变成100。'),
(48348921, 'Number C62: Neo Galaxy-Eyes Prime Photon Dragon', '混沌编号62 超银河眼光子龙皇', 'CNo.62 超銀河眼の光子龍皇', 'XYZ Monster', 'Dragon', 'LIGHT', 8, 4000, 3000, '光属性8星怪兽×3 这张卡也能在自己场上的「No.62 银河眼光子龙皇」上面重叠来超量召唤。 ①：自己战斗阶段开始时，把这张卡1个超量素材取除才能发动。这张卡在这次战斗阶段中最多3次可以向怪兽攻击。 ②：这张卡有「银河眼光子龙」在作为超量素材的场合，得到以下效果。 ●这张卡不受对方怪兽的效果影响。 ●这张卡的攻击力上升这张卡作为超量素材中的怪兽的等级·阶级的合计×100。'),
(49195710, 'Number C65: King Overfiend', '混沌编号65 裁断魔王 裁决恶鬼', 'CNo.65 裁断魔王ジャッジ・デビル', 'XYZ Monster', 'Fiend', 'DARK', 3, 1600, NULL, '暗属性3星怪兽×3 ①：1回合1次，把这张卡1个超量素材取除，以对方场上1只表侧表示怪兽为对象才能发动。那只怪兽的攻击力·守备力下降1000。 ②：这张卡有「No.65 裁断魔人」在作为超量素材的场合，得到以下效果。 ●只要这张卡在怪兽区域存在，对方场上的怪兽不能把效果发动。'),
(11522979, 'Number C69: Heraldry Crest of Horror', '混沌编号69 徽章死神 混盾徽', 'CNo.69 紋章死神カオス・オブ・アームズ', 'XYZ Monster', 'Psychic', 'LIGHT', 5, 4000, 1800, '5星怪兽×4 ①：对方怪兽的攻击宣言时才能发动。对方场上的卡全部破坏。 ②：这张卡有「No.69 纹章神 盾徽」在作为超量素材的场合，得到以下效果。 ●1回合1次，把这张卡1个超量素材取除，以对方场上1只超量怪兽为对象才能发动。直到结束阶段，这张卡的攻击力上升那只怪兽的原本攻击力数值，这张卡得到和那只怪兽的原本的卡名·效果相同的卡名·效果。'),
(96864105, 'Number C73: Abyss Supra Splash', '混沌编号73 激泷瀑神 邃渊涌溅', 'CNo.73 激瀧瀑神アビス・スープラ', 'XYZ Monster', 'Warrior', 'WATER', 6, 3000, 2000, '6星怪兽×3 ①：自己怪兽和对方怪兽进行战斗的伤害计算时1次，把这张卡1个超量素材取除才能发动。那只自己怪兽的攻击力只在那次伤害计算时上升那只对方怪兽的攻击力数值。 ②：这张卡有「No.73 激泷神 渊涛」在作为超量素材的场合，得到以下效果。 ●这张卡不会被效果破坏。'),
(10300821, 'Number C79: Battlin'' Boxer General Kaiser', '混沌编号79 燃烧拳斗士 将星之指虎', 'CNo.79 BK 将星のカエサル', 'XYZ Monster', 'Warrior', 'FIRE', 5, 2600, 2000, '5星怪兽×3 ①：这张卡的攻击力上升这张卡的超量素材数量×200。 ②：1回合1次，对方把怪兽特殊召唤之际才能发动。这张卡2个超量素材取除，那个无效并破坏。 ③：这张卡有「No.79 燃烧拳击手 新星之帝环拳士」在作为超量素材的场合，得到以下效果。 ●1回合1次，自己的「燃烧拳击手」怪兽和对方怪兽进行战斗的攻击宣言时才能发动。从手卡·卡组把1只「燃烧拳击手」怪兽送去墓地，那只对方怪兽作为这张卡的超量素材。'),
(20563387, 'Number C80: Requiem in Berserk', '混沌编号80 葬装霸王 狂战镇魂曲', 'CNo.80 葬装覇王レクイエム・イン・バーサーク', 'XYZ Monster', 'Fiend', 'DARK', 5, NULL, 2000, '5星怪兽×3 ①：以自己场上1只超量怪兽为对象才能发动。自己场上的这张卡当作攻击力上升2000的装备卡使用给那只自己怪兽装备。 ②：装备怪兽被破坏的场合，作为代替把这张卡破坏。 ③：这张卡有「No.80 狂装霸王 狂想战曲王」在作为超量素材的场合，得到以下效果。 ●把这张卡1个超量素材取除，以场上1张卡为对象才能发动。那张卡除外。'),
(6165656, 'Number C88: Gimmick Puppet Disaster Leo', '混沌编号88 机关傀偶－灾厄之狮', 'CNo.88 ギミック・パペット－ディザスター・レオ', 'XYZ Monster', 'Machine', 'DARK', 9, 3500, 2500, '9星怪兽×4 这张卡用以「No.88 机关傀儡-命运狮子」为对象的「升阶魔法」魔法卡的效果才能特殊召唤。自己结束阶段，对方基本分是2000以下而这张卡没有超量素材的场合，自己决斗胜利。 ①：场上的这张卡不会成为效果的对象。 ②：1回合1次，把这张卡1个超量素材取除才能发动。给与对方1000伤害。'),
(32559361, 'Number C9: Chaos Dyson Sphere', '混沌No.9 天盖妖星 混沌戴森球', 'CNo.9 天蓋妖星カオス・ダイソン・スフィア', 'XYZ Monster', 'Machine', 'LIGHT', 10, 3600, 3200, '10星怪兽×3 ①：1回合1次，自己主要阶段才能发动。给与对方这张卡的超量素材数量×300伤害。 ②：这张卡和对方怪兽进行战斗的伤害步骤开始时才能发动。那只怪兽在这张卡下面重叠作为超量素材。 ③：这张卡有「No.9 天盖星 戴森球」在作为超量素材的场合，得到以下效果。 ●1回合1次，把这张卡的超量素材任意数量取除才能发动。给与对方取除数量×800伤害。'),
(47017574, 'Number C92: Heart-eartH Chaos Dragon', '混沌编号92 伪骸虚龙 心地心混沌龙', 'CNo.92 偽骸虚龍 Heart－eartH Chaos Dragon', 'XYZ Monster', 'Dragon', 'DARK', 10, 1000, NULL, '10星怪兽×4 ①：这张卡不会被战斗破坏。 ②：自己怪兽给与对方战斗伤害的场合发动。自己基本分回复那个数值。 ③：这张卡有「No.92 伪骸神龙 心地心龙」在作为超量素材的场合，得到以下效果。 ●1回合1次，把这张卡1个超量素材取除才能发动。对方场上的全部表侧表示的卡的效果直到回合结束时无效化。这个效果的发动和效果不会被无效化。'),
(77205367, 'Number C96: Dark Storm', '混沌No.96 黑飙', 'CNo.96 ブラック・ストーム', 'XYZ Monster', 'Fiend', 'DARK', 3, 1000, 1000, '暗属性3星怪兽×4 ①：这张卡不会被战斗破坏，这张卡的战斗发生的对自己的战斗伤害让对方也承受。 ②：这张卡有「No.96 黑雾」在作为超量素材的场合，得到以下效果。 ●这张卡和对方怪兽进行战斗的攻击宣言时1次，把这张卡1个超量素材取除才能发动。那只对方怪兽的攻击力变成0，这张卡的攻击力上升那只对方怪兽的原本攻击力数值。'),
(26973555, 'Number F0: Utopic Draco Future', '翼日编号0 未来龙皇霍普', 'FNo.0 未来龍皇ホープ', 'XYZ Monster', 'Warrior', 'LIGHT', NULL, 3000, 2000, '「No.」怪兽以外的相同阶级的超量怪兽×3 规则上，这张卡的阶级当作1阶使用，这个卡名也当作「未来皇 霍普」卡使用。这张卡也能在自己场上的「未来No.0 未来皇 霍普」上面重叠来超量召唤。 ①：这张卡不会被战斗·效果破坏。 ②：1回合1次，对方把怪兽的效果发动时，把这张卡1个超量素材取除才能发动。那个发动无效。这个效果把场上的怪兽的效果的发动无效的场合，再得到那个控制权。'),
(65305468, 'Number F0: Utopic Future', '翼日编号0 未来皇霍普', 'FNo.0 未来皇ホープ', 'XYZ Monster', 'Warrior', 'LIGHT', NULL, NULL, NULL, '「No.」怪兽以外的相同阶级的超量怪兽×2 规则上，这张卡的阶级当作1阶使用。 ①：这张卡不会被战斗破坏，这张卡的战斗发生的双方的战斗伤害变成0。 ②：这张卡和对方怪兽进行战斗的伤害步骤结束时才能发动。那只对方怪兽的控制权直到战斗阶段结束时得到。 ③：场上的这张卡被效果破坏的场合，可以作为代替把这张卡1个超量素材取除。'),
(43490025, 'Number F0: Utopic Future Slash', '翼日编号0 未来皇霍普－翼日斩', 'FNo.0 未来皇ホープ－フューチャー・スラッシュ', 'XYZ Monster', 'Warrior', 'LIGHT', NULL, NULL, NULL, '「No.」怪兽以外的相同阶级的超量怪兽×2 规则上，这张卡的阶级当作1阶使用。这张卡也能在自己场上的「希望皇 霍普」怪兽或者「未来No.0 未来皇 霍普」上面重叠来超量召唤。 ①：这张卡的攻击力上升双方墓地的「No.」超量怪兽数量×500。 ②：这张卡不会被战斗破坏。 ③：1回合1次，把这张卡1个超量素材取除才能发动。这个回合，这张卡在同1次的战斗阶段中可以作2次攻击。'),
(41522092, 'Number F0: Utopic Future Zexal', '翼日编号0 未来皇霍普ZEXAL', 'FNo.0 未来皇ホープ・ゼアル', 'XYZ Monster', 'Warrior', 'LIGHT', NULL, NULL, NULL, '相同阶级的超量怪兽×2 规则上，这张卡的阶级当作1阶使用。 ①：这张卡的攻击力·守备力上升自己场上以及对方墓地的超量怪兽的阶级合计×500。 ②：对方怪兽不能选择其他怪兽作为攻击对象，对方不能把场上的其他卡作为效果的对象。 ③：1回合1次，对方在场上把效果发动时，把这张卡1个超量素材取除才能发动。得到对方场上1只怪兽的控制权。这个回合，这张卡不会被战斗·效果破坏。'),
(15862758, 'Number iC1000: Numerounius Numerounia', '混沌虚数No.1000 梦幻虚光神 原数天灵·原数天地', 'CiNo.1000 夢幻虚光神ヌメロニアス・ヌメロニア', 'XYZ Monster', 'Fiend', 'LIGHT', 13, -1, -1, '13星怪兽×5 ①：「混沌No.1000 梦幻虚神 原数天灵」的效果特殊召唤的这张卡攻击力·守备力只在对方回合内上升100000，从特殊召唤的下个回合起以下适用。 ●可以攻击的对方怪兽必须向这张卡作出攻击。 ●这张卡没有进行战斗的对方回合结束时，自己决斗胜利。 ②：对方怪兽的攻击宣言时，把这张卡1个超量素材取除才能发动。那次攻击无效，自己基本分回复那个攻击力的数值。'),
(52653092, 'Number S0: Utopic ZEXAL', '闪光No.0 霍普·异热同心', 'SNo.0 ホープ・ゼアル', 'XYZ Monster', 'Warrior', 'LIGHT', NULL, -1, -1, '相同阶级的「No.」超量怪兽×3 规则上，这张卡的阶级当作1阶使用。这张卡也能把手卡1张「升阶魔法」通常魔法卡丢弃，在自己场上的「希望皇 霍普」怪兽上面重叠来超量召唤。 ①：这张卡的超量召唤不会被无效化。 ②：在这张卡的超量召唤成功时，对方不能把效果发动。 ③：这张卡的攻击力·守备力上升这张卡的超量素材数量×1000。 ④：对方回合1次，把这张卡1个超量素材取除才能发动。这个回合对方不能把效果发动。'),
(79625003, 'Number S37: Spider Shark', '闪光编号37 蜘蛛鲨', 'SNo.37 スパイダー・シャーク', 'XYZ Monster', 'Sea Serpent', 'WATER', 5, 2600, 2100, '水属性5星怪兽×3 这张卡也能在自己场上的「No.37 希望织龙 蜘蛛鲨」上面重叠来超量召唤。 ①：1回合1次，把这张卡1个超量素材取除，以对方场上1只怪兽为对象才能发动。那只怪兽直到下次的对方准备阶段除外，对方场上有怪兽存在的场合，那些攻击力直到回合结束时下降1000。 ②：超量召唤的这张卡被破坏送去墓地的回合的结束阶段才能发动。这张卡特殊召唤。'),
(16110708, 'Number S38: Titanic Galaxy', '闪光编号38 泰坦银河', 'SNo.38 タイタニック・ギャラクシー', 'XYZ Monster', 'Dragon', 'LIGHT', 9, 3000, 2500, '光属性9星怪兽×3 这张卡也能在自己场上的「No.38 希望魁龙 银河巨神」上面重叠来超量召唤。 ①：这张卡的攻击力上升这张卡的超量素材数量×200。 ②：1回合1次，以对方场上最多2张魔法·陷阱卡为对象才能发动（不能对应这个发动把作为对象的卡的效果发动）。那些卡作为这张卡的超量素材。 ③：把这张卡1个超量素材取除才能发动。这个回合，这张卡的原本攻击力变成1500，可以直接攻击。'),
(86532744, 'Number S39: Utopia Prime', '闪光编号39 希望皇霍普・壹', 'SNo.39 希望皇ホープONE', 'XYZ Monster', 'Warrior', 'LIGHT', 4, 2510, 2000, '光属性4星怪兽×3 这张卡也能在自己场上的「No.39 希望皇 霍普」上面重叠来超量召唤。 ①：自己基本分比对方少3000以上的场合，把这张卡3个超量素材取除，把基本分支付到变成10基本分才能发动。对方场上的特殊召唤的怪兽全部破坏并除外。那之后，给与对方这个效果除外的怪兽数量×300伤害。'),
(56832966, 'Number S39: Utopia the Lightning', '闪光编号39 希望皇霍普・雷霆', 'SNo.39 希望皇ホープ・ザ・ライトニング', 'XYZ Monster', 'Warrior', 'LIGHT', 5, 2500, 2000, '光属性5星怪兽×3 这张卡也能在自己场上的4阶「希望皇 霍普」怪兽上面重叠来超量召唤。这张卡不能作为超量召唤的素材。 ①：这张卡进行战斗的场合，对方直到伤害步骤结束时卡的效果不能发动。 ②：这张卡有「希望皇 霍普」怪兽在作为超量素材的场合，这张卡和对方怪兽进行战斗的伤害计算时1次，把这张卡2个超量素材取除才能发动。这张卡的攻击力只在那次伤害计算时变成5000。');